var EXAMS_BASE = [{"id": "2027-g6-p1-quiz1", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Quiz 1 — Coordinación, equilibrio y buena postura (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Coordinación, equilibrio y postura", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "La coordinación es la capacidad de mover varias partes del cuerpo de forma ordenada para lograr un movimiento eficaz. Cuando intervienen todo el cuerpo y grandes grupos musculares, como al saltar la cuerda o al correr esquivando conos, se habla de coordinación dinámica general. Cuando la vista guía el trabajo de las manos, como al lanzar y atrapar, se llama coordinación óculo-manual; y cuando guía el trabajo de los pies, como al conducir un balón, se llama coordinación óculo-pédica.<br><br>El equilibrio es la capacidad de mantener el cuerpo controlado. Es estático cuando el cuerpo está quieto, por ejemplo al sostenerse en un pie, y dinámico cuando se mantiene el control en movimiento, como al caminar sobre una línea o un banco. La postura es la posición que adopta el cuerpo de pie, sentado o al moverse. Una buena postura mantiene la espalda recta, los hombros relajados y el peso repartido; así se protege la columna y se gasta menos energía. Por eso conviene revisar cómo nos sentamos en el aula y cómo cargamos el morral."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la coordinación es la capacidad de:", "opciones": {"A": "mantener el cuerpo completamente quieto.", "B": "mover varias partes del cuerpo de forma ordenada para lograr un movimiento eficaz.", "C": "correr la mayor distancia posible.", "D": "levantar objetos pesados."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Lanzar y atrapar un balón es un ejemplo de coordinación:", "opciones": {"A": "óculo-manual.", "B": "óculo-pédica.", "C": "estática.", "D": "postural."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "El equilibrio es estático cuando:", "opciones": {"A": "el cuerpo se mueve sobre un banco.", "B": "se conduce un balón con el pie.", "C": "el cuerpo se mantiene controlado estando quieto.", "D": "se corre esquivando conos."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «eficaz» significa:", "opciones": {"A": "que se hace muy despacio.", "B": "que se repite muchas veces.", "C": "que no necesita práctica.", "D": "que logra bien lo que se propone."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué una buena postura ayuda a gastar menos energía?", "opciones": {"A": "Porque el cuerpo reparte el peso y no hace esfuerzos innecesarios.", "B": "Porque obliga a quedarse quieto todo el día.", "C": "Porque reemplaza el ejercicio.", "D": "Porque hace que los músculos dejen de trabajar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante camina sobre un banco sin perder el control. ¿Qué capacidad está usando?", "opciones": {"A": "El equilibrio estático.", "B": "El equilibrio dinámico.", "C": "La coordinación óculo-manual.", "D": "La fuerza máxima."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cuál es la forma más adecuada de cargar el morral?", "opciones": {"A": "En un solo hombro, inclinando el cuerpo.", "B": "Colgado de la mano con el brazo estirado.", "C": "En la espalda baja, encorvado hacia adelante.", "D": "En los dos hombros, con la espalda recta."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Conducir un balón esquivando conos exige sobre todo:", "opciones": {"A": "equilibrio estático.", "B": "coordinación óculo-manual.", "C": "coordinación óculo-pédica.", "D": "flexibilidad de los brazos."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, una buena postura mantiene:", "opciones": {"A": "la espalda recta, los hombros relajados y el peso repartido.", "B": "la cabeza siempre hacia abajo.", "C": "todo el peso sobre una sola pierna.", "D": "los hombros levantados y tensos."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué es importante revisar cómo nos sentamos en el aula?", "opciones": {"A": "Porque así se termina más rápido la clase.", "B": "Porque pasamos muchas horas sentados y una mala postura puede afectar la columna.", "C": "Porque la postura no tiene relación con la salud.", "D": "Porque solo importa la postura al hacer deporte."}}]}, {"id": "2027-g6-p1-quiz2", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Quiz 2 — Lateralidad, espacio y tiempo (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Ubicarse en el espacio y en el tiempo", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "La lateralidad es la preferencia por usar un lado del cuerpo más que el otro: hay personas diestras, que prefieren la mano o el pie derecho, y personas zurdas, que prefieren el izquierdo. Reconocer la derecha y la izquierda en el propio cuerpo, y luego en el de un compañero que está de frente, ayuda a moverse con seguridad en los juegos.<br><br>Las nociones espaciales permiten ubicarse y ubicar objetos: delante y detrás, arriba y abajo, cerca y lejos, dentro y fuera. Las nociones temporales tienen que ver con el tiempo del movimiento: el orden en que ocurren las acciones (antes, durante, después), la duración (cuánto tarda algo), la velocidad (rápido o lento) y el ritmo, que es la repetición ordenada de movimientos o sonidos, como al saltar la cuerda siguiendo una canción. En los juegos de orientación y en los relevos se usan todas estas nociones: hay que saber hacia dónde ir, en qué orden salir y cuándo entregar el testigo."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la lateralidad es:", "opciones": {"A": "la capacidad de correr en línea recta.", "B": "la habilidad de saltar la cuerda.", "C": "la preferencia por usar un lado del cuerpo más que el otro.", "D": "el orden en que ocurren las acciones."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Una persona que prefiere usar la mano izquierda es:", "opciones": {"A": "diestra.", "B": "zurda.", "C": "ambidiestra.", "D": "lateral."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál de estas es una noción espacial?", "opciones": {"A": "Antes y después.", "B": "Rápido y lento.", "C": "Corto y largo en minutos.", "D": "Cerca y lejos."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «ritmo» significa:", "opciones": {"A": "la repetición ordenada de movimientos o sonidos.", "B": "la fuerza con que se lanza un balón.", "C": "el lugar donde se ubica un objeto.", "D": "la preferencia por un lado del cuerpo."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué cuesta más reconocer la derecha de un compañero que está de frente?", "opciones": {"A": "Porque los compañeros no tienen lateralidad.", "B": "Porque su derecha queda al lado contrario de la nuestra.", "C": "Porque la derecha cambia cada día.", "D": "Porque solo se puede reconocer con los ojos cerrados."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un relevo, ¿qué noción temporal se usa al decidir quién sale primero?", "opciones": {"A": "La noción de arriba y abajo.", "B": "La noción de dentro y fuera.", "C": "El orden de las acciones.", "D": "La preferencia lateral."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "El profesor dice: «pon el cono detrás de ti y el aro delante». ¿Qué nociones está usando?", "opciones": {"A": "Nociones espaciales.", "B": "Nociones temporales.", "C": "Nociones de lateralidad únicamente.", "D": "Nociones de ritmo."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "En un juego de orientación, un equipo llega a un punto pero no sabe hacia dónde seguir. ¿Qué le está fallando?", "opciones": {"A": "La duración del juego.", "B": "La velocidad de los saltos.", "C": "El ritmo de la canción.", "D": "La ubicación en el espacio."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la duración se refiere a:", "opciones": {"A": "qué tan lejos está un objeto.", "B": "cuánto tarda algo.", "C": "con qué lado del cuerpo se lanza.", "D": "qué tan alto se salta."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué son útiles estas nociones fuera de la clase de Educación Física?", "opciones": {"A": "Porque solo sirven para ganar relevos.", "B": "Porque reemplazan el estudio de otras materias.", "C": "Porque ayudan a orientarse y a moverse con seguridad en la vida diaria.", "D": "Porque no tienen ninguna utilidad fuera del colegio."}}]}, {"id": "2027-g6-p1-taller", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Taller escrito digital — Expresión corporal: el cuerpo comunica (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "El cuerpo también habla", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Además de las palabras, las personas se comunican con el cuerpo. Los gestos de la cara, la postura, la mirada y los movimientos de las manos transmiten mensajes, muchas veces sin que nos demos cuenta. Una sonrisa invita a acercarse; los brazos cruzados pueden mostrar enojo o frío; una cabeza baja puede indicar tristeza o cansancio. A esto se le llama comunicación no verbal.<br><br>La expresión corporal es la forma de usar el cuerpo, de manera consciente, para comunicar ideas, sentimientos y emociones. Se trabaja con juegos, dramatizaciones y danzas. No se trata de hacerlo «bonito», sino de que el mensaje se entienda. Por eso, antes de expresar algo, conviene observar cómo se mueven las personas y qué gestos usan en distintas situaciones."}, {"id": 2, "titulo": "La mímica: contar sin palabras", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "La mímica es el arte de representar acciones, objetos o personajes solo con gestos y movimientos, sin hablar ni usar sonidos. Para que el público entienda, los movimientos deben ser claros y un poco más grandes de lo normal; a esto se le llama exagerar el gesto. También es importante imaginar los objetos con precisión: si se abre una puerta invisible, la mano debe tomar la manija siempre en el mismo lugar.<br><br>Una buena mímica tiene un comienzo, un desarrollo y un final, como un cuento corto. La cara acompaña lo que hace el cuerpo: si el personaje carga algo pesado, el rostro muestra esfuerzo. Antes de presentar se ensaya varias veces y se pide a un compañero que diga qué entendió."}, {"id": 3, "titulo": "Emociones en movimiento y montaje grupal", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Cada emoción se puede expresar con el cuerpo. La alegría suele mostrarse con movimientos amplios, rápidos y hacia arriba; la tristeza, con movimientos lentos, pequeños y hacia abajo; el miedo, encogiendo el cuerpo y alejándose; el enojo, con movimientos fuertes y tensos. El ritmo y la velocidad también cambian el mensaje.<br><br>En un montaje grupal, varios estudiantes crean juntos una pequeña obra con movimientos, gestos y música. Para lograrlo deben escuchar las ideas de todos, repartir los papeles, ensayar y respetar el turno de cada compañero. Lo importante no es quién lo hace mejor, sino que el grupo comunique su idea con creatividad y respeto."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la comunicación no verbal se da a través de:", "opciones": {"A": "los gestos, la postura, la mirada y los movimientos.", "B": "las palabras escritas.", "C": "las llamadas telefónicas.", "D": "los mensajes de texto."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué puede indicar una cabeza baja, según el texto?", "opciones": {"A": "Alegría.", "B": "Tristeza o cansancio.", "C": "Enojo intenso.", "D": "Ganas de competir."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, hacer algo «de manera consciente» significa hacerlo:", "opciones": {"A": "sin pensar.", "B": "dormido.", "C": "dándose cuenta y con intención.", "D": "por accidente."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto dice que la expresión corporal no se trata de hacerlo «bonito»?", "opciones": {"A": "Porque los movimientos deben ser feos.", "B": "Porque no importa lo que se comunique.", "C": "Porque solo se evalúa la ropa.", "D": "Porque lo importante es que el mensaje se entienda."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero cruza los brazos y frunce el ceño cuando pierde un juego. ¿Qué está comunicando con el cuerpo?", "opciones": {"A": "Alegría.", "B": "Enojo o frustración.", "C": "Cansancio por sueño.", "D": "Ganas de abrazar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Antes de expresar una emoción con el cuerpo, el texto recomienda:", "opciones": {"A": "memorizar un discurso largo.", "B": "evitar mirar a los demás.", "C": "observar cómo se mueven las personas en distintas situaciones.", "D": "hablar lo más fuerte posible."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué es importante aprender a leer el lenguaje del cuerpo de los compañeros?", "opciones": {"A": "Porque permite burlarse de ellos.", "B": "Porque reemplaza el diálogo.", "C": "Porque solo sirve para el teatro.", "D": "Porque ayuda a entender cómo se sienten y a convivir mejor."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "Según el texto, la mímica representa acciones y objetos:", "opciones": {"A": "solo con gestos y movimientos, sin hablar.", "B": "con palabras y canciones.", "C": "con dibujos en el tablero.", "D": "con sonidos de la boca."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué partes debe tener una buena mímica?", "opciones": {"A": "Solo un final sorpresa.", "B": "Únicamente el comienzo.", "C": "Preguntas al público.", "D": "Comienzo, desarrollo y final."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, «exagerar el gesto» significa:", "opciones": {"A": "hacer el gesto muy pequeño.", "B": "hacer el movimiento un poco más grande de lo normal para que se entienda.", "C": "decir en voz alta lo que se representa.", "D": "repetir el gesto sin ninguna intención."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué la mano debe tomar la manija de la puerta invisible siempre en el mismo lugar?", "opciones": {"A": "Para cansar menos el brazo.", "B": "Porque así lo exige un reglamento deportivo.", "C": "Para que el público crea que el objeto existe y entienda la acción.", "D": "Para que la mímica dure más."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante representa que carga una caja pesada, pero sonríe y camina ligero. ¿Qué debe corregir?", "opciones": {"A": "Mostrar esfuerzo con el rostro y con el cuerpo.", "B": "Hablar para explicar que la caja pesa.", "C": "Usar una caja de verdad.", "D": "Hacer el movimiento más rápido."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "Después de ensayar, ¿qué se recomienda hacer?", "opciones": {"A": "Presentar sin volver a revisar.", "B": "Cambiar toda la mímica al azar.", "C": "Pedir a un compañero que diga qué entendió.", "D": "Hacerla con los ojos cerrados."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué valor tiene ensayar varias veces antes de presentar?", "opciones": {"A": "Ninguno, porque la mímica sale sola.", "B": "Solo sirve para gastar tiempo.", "C": "Hace que el público se aburra.", "D": "Permite corregir y lograr que el mensaje sea claro."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "Según el texto, ¿cómo suele expresarse la tristeza con el cuerpo?", "opciones": {"A": "Con movimientos lentos, pequeños y hacia abajo.", "B": "Con movimientos amplios y rápidos hacia arriba.", "C": "Con saltos fuertes y tensos.", "D": "Con giros veloces."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, un «montaje grupal» es:", "opciones": {"A": "un juego de fútbol por equipos.", "B": "una pequeña obra creada por varios estudiantes con movimientos, gestos y música.", "C": "un examen individual.", "D": "una lista de reglas del aula."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el ritmo y la velocidad cambian el mensaje de un movimiento?", "opciones": {"A": "Porque un mismo gesto lento o rápido transmite emociones distintas.", "B": "Porque el ritmo no influye en nada.", "C": "Porque solo importa la música.", "D": "Porque la velocidad elimina el gesto."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "En un montaje grupal, dos compañeros quieren el mismo papel. ¿Qué es lo más adecuado?", "opciones": {"A": "Que gane quien grite más.", "B": "Abandonar el montaje.", "C": "Dialogar, escuchar las ideas y acordar una solución entre todos.", "D": "Dejar el papel sin hacer."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿qué es lo más importante en un montaje grupal?", "opciones": {"A": "Saber quién lo hace mejor.", "B": "Que el grupo comunique su idea con creatividad y respeto.", "C": "Terminar antes que los demás.", "D": "Que solo participe el líder."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Relacionando las tres lecturas, ¿qué se necesita para comunicar bien con el cuerpo?", "opciones": {"A": "Hablar mientras se hacen los gestos.", "B": "Moverse al azar sin ensayar.", "C": "Copiar exactamente a un compañero sin pensar en el mensaje.", "D": "Usar gestos claros y conscientes, mostrar la emoción con todo el cuerpo y trabajar con respeto en grupo."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g7-p1-quiz1", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Quiz 1 — Fundamentos técnicos de microfútbol y baloncesto (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Los fundamentos técnicos", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Los fundamentos técnicos son los movimientos básicos que un jugador necesita para participar en un deporte. En el microfútbol, la conducción consiste en avanzar con el balón controlado con toques suaves y cortos, con la cabeza levantada para ver a los compañeros. El pase con el borde interno del pie es el más preciso para distancias cortas: el pie de apoyo se ubica al lado del balón y el pie que golpea se gira hacia afuera. El control o recepción es detener o dominar el balón que llega, y el remate es el golpe que busca hacer gol.<br><br>En el baloncesto, el drible o bote se hace con la yema de los dedos, no con la palma, y con la mirada al frente. El pase de pecho sale desde el pecho, con las dos manos, hacia el pecho del compañero; el pase picado se hace rebotando el balón en el piso antes de que llegue al compañero, y sirve para superar a un defensor que tiene los brazos arriba. Dominar los fundamentos permite jugar con más seguridad y disfrutar del juego."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál es el pase más preciso para distancias cortas en microfútbol?", "opciones": {"A": "El pase con el borde interno del pie.", "B": "El pase con la punta del pie.", "C": "El pase con el talón.", "D": "El pase con la rodilla."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "En baloncesto, el drible se hace con:", "opciones": {"A": "la palma de la mano.", "B": "el puño cerrado.", "C": "las dos manos al tiempo.", "D": "la yema de los dedos."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué consiste el pase picado?", "opciones": {"A": "En lanzar el balón por encima de la cabeza.", "B": "En rebotar el balón en el piso antes de que llegue al compañero.", "C": "En pasar el balón con el pie.", "D": "En botar el balón sin soltarlo."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «conducción» se refiere a:", "opciones": {"A": "patear el balón lo más lejos posible.", "B": "detener el juego.", "C": "avanzar con el balón controlado con toques suaves y cortos.", "D": "lanzar el balón al aro."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué conviene conducir y driblar con la cabeza levantada?", "opciones": {"A": "Para no mirar el balón nunca.", "B": "Para correr más despacio.", "C": "Porque así lo exige el árbitro.", "D": "Para ver a los compañeros y a los rivales y decidir mejor."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un defensor tiene los brazos arriba y tapa el pase de pecho. ¿Qué pase conviene usar?", "opciones": {"A": "El pase picado.", "B": "Otro pase de pecho más fuerte.", "C": "Un remate al aro.", "D": "Un pase con el pie."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Al dar un pase con el borde interno, ¿dónde se ubica el pie de apoyo?", "opciones": {"A": "Detrás del compañero.", "B": "Encima del balón.", "C": "Al lado del balón.", "D": "Lejos del balón, a dos pasos."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Un jugador recibe el balón y lo deja escapar lejos de su cuerpo. ¿Qué fundamento debe mejorar?", "opciones": {"A": "El remate.", "B": "El control o recepción.", "C": "El pase picado.", "D": "El salto entre dos."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el remate es:", "opciones": {"A": "el pase hacia atrás.", "B": "la forma de botar el balón.", "C": "la falta más grave.", "D": "el golpe que busca hacer gol."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué es importante dominar los fundamentos técnicos?", "opciones": {"A": "Porque permiten jugar con más seguridad y disfrutar del juego.", "B": "Porque reemplazan el trabajo en equipo.", "C": "Porque así no hace falta respetar las reglas.", "D": "Porque solo los necesitan los profesionales."}}]}, {"id": "2027-g7-p1-quiz2", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Quiz 2 — Reglas básicas de microfútbol y baloncesto (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Faltas, saques y puntuación", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En el microfútbol, cada equipo tiene cinco jugadores, uno de ellos el portero. Se anota un gol cuando el balón cruza completamente la línea de la portería. Cuando el balón sale por una línea lateral, el juego se reanuda con un saque de banda a favor del equipo que no lo tocó de último. Empujar, hacer zancadilla, sujetar al rival o jugar el balón con la mano (salvo el portero en su área) son faltas que se sancionan con un tiro libre para el otro equipo. La tarjeta amarilla es una advertencia y la roja significa expulsión.<br><br>En el baloncesto, una canasta durante el juego vale dos puntos, y tres si se lanza desde detrás de la línea de tres puntos; cada tiro libre convertido vale un punto. Son violaciones caminar con el balón sin botarlo (pasos) y volver a botar después de haber agarrado el balón con las dos manos (doble drible); se sancionan con la pérdida del balón. Las faltas personales son contactos ilegales, como empujar o golpear al rival. En los juegos reducidos 3 contra 3 de la clase, los mismos estudiantes arbitran y deben aplicar estas reglas con imparcialidad."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuántos jugadores tiene cada equipo de microfútbol?", "opciones": {"A": "Once.", "B": "Siete.", "C": "Cinco, uno de ellos el portero.", "D": "Tres."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos puntos vale una canasta lanzada desde detrás de la línea de tres puntos?", "opciones": {"A": "Tres puntos.", "B": "Un punto.", "C": "Dos puntos.", "D": "Cuatro puntos."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "En baloncesto, ¿cuánto vale cada tiro libre convertido?", "opciones": {"A": "Dos puntos.", "B": "Un punto.", "C": "Tres puntos.", "D": "No vale puntos."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, actuar con «imparcialidad» significa:", "opciones": {"A": "favorecer al equipo de los amigos.", "B": "pitar solo las faltas graves.", "C": "dejar que los jugadores decidan.", "D": "aplicar las reglas por igual a los dos equipos."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué caminar con el balón sin botarlo se sanciona con la pérdida del balón?", "opciones": {"A": "Porque daría una ventaja injusta al avanzar sin cumplir la regla del bote.", "B": "Porque es una falta de contacto violenta.", "C": "Porque el jugador debe salir expulsado.", "D": "Porque así se acaba el partido."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "En microfútbol, el balón sale por la línea lateral después de que lo toca un jugador del equipo azul. ¿Qué se cobra?", "opciones": {"A": "Un saque de banda para el equipo azul.", "B": "Un penal para el equipo azul.", "C": "Un saque de banda para el equipo contrario.", "D": "Un salto entre dos."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador de baloncesto agarra el balón con las dos manos y vuelve a botarlo. ¿Qué se sanciona?", "opciones": {"A": "Falta personal y tiro libre.", "B": "Tres puntos para el rival.", "C": "Nada, porque es permitido.", "D": "Doble drible: pierde el balón."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Un jugador de microfútbol recibe tarjeta amarilla. ¿Qué significa?", "opciones": {"A": "Que es expulsado.", "B": "Que recibe una advertencia.", "C": "Que su equipo gana un gol.", "D": "Que debe cambiar de portero."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuándo se anota un gol en microfútbol?", "opciones": {"A": "Cuando el balón cruza completamente la línea de la portería.", "B": "Cuando el balón toca el palo.", "C": "Cuando el portero toca el balón.", "D": "Cuando el balón pisa la línea sin cruzarla."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Como árbitro estudiantil, un compañero ve una falta de su mejor amigo. ¿Qué debe hacer?", "opciones": {"A": "Ignorarla para no molestar a su amigo.", "B": "Pitar una falta inventada al otro equipo.", "C": "Sancionarla, porque las reglas se aplican igual para todos.", "D": "Detener el partido para siempre."}}]}, {"id": "2027-g7-p1-taller", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Taller escrito digital — Los fundamentos técnicos y su correcta ejecución (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Conducción y pase en microfútbol", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Para conducir bien el balón se usan toques cortos con el borde interno o externo del pie, manteniendo el balón cerca para no perderlo. El cuerpo va un poco inclinado hacia adelante, las rodillas semiflexionadas y la cabeza levantada para ver el espacio libre y a los compañeros. Cuando hay un rival cerca, se protege el balón poniendo el cuerpo entre él y el defensor.<br><br>En el pase con el borde interno, el pie de apoyo se ubica al lado del balón y apunta hacia el compañero; el pie que golpea se gira hacia afuera y toca el centro del balón. Después del golpe, la pierna acompaña el movimiento en dirección al compañero. Un pase demasiado fuerte es difícil de controlar, y uno muy suave puede ser interceptado: la fuerza debe ajustarse a la distancia."}, {"id": 2, "titulo": "Drible y pase en baloncesto", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "En el drible, el balón se impulsa hacia el piso con la yema de los dedos, flexionando la muñeca; la palma no golpea el balón. El bote no debe subir más arriba de la cintura, y el cuerpo protege el balón con el brazo libre. Es importante driblar con las dos manos para no ser predecible: con la mano derecha cuando el defensor está a la izquierda, y al contrario.<br><br>En el pase de pecho, el balón se sostiene con las dos manos a la altura del pecho, los codos cerca del cuerpo; se da un paso hacia el compañero y se extienden los brazos, girando las manos hacia afuera al soltar. En el pase picado, el balón debe rebotar más cerca del compañero que de quien pasa, para que llegue a la altura de la cintura."}, {"id": 3, "titulo": "El lanzamiento: bandeja y remate", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "La bandeja es un lanzamiento en carrera, muy cerca del aro. Si se ataca por la derecha, se dan dos pasos: el primero con el pie derecho y el segundo con el izquierdo, que es el pie de impulso; se salta hacia arriba levantando la rodilla derecha y se deja el balón suavemente contra el tablero con la mano derecha. Por la izquierda, todo se hace al contrario.<br><br>En el microfútbol, el remate busca precisión antes que fuerza. El pie de apoyo se ubica al lado del balón, el cuerpo va ligeramente sobre el balón para que no se eleve demasiado, y se golpea con el empeine o con el borde interno, según la distancia. Mirar la posición del portero antes de rematar ayuda a elegir el lugar del arco más difícil de cubrir."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, al conducir el balón conviene mantenerlo:", "opciones": {"A": "cerca del pie, con toques cortos.", "B": "lo más lejos posible.", "C": "siempre en el aire.", "D": "detenido bajo la suela."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se protege el balón cuando hay un rival cerca?", "opciones": {"A": "Pateándolo hacia afuera.", "B": "Tomándolo con la mano.", "C": "Poniendo el cuerpo entre el balón y el defensor.", "D": "Cerrando los ojos."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «interceptado» significa:", "opciones": {"A": "que el balón llega perfecto al compañero.", "B": "que un rival corta el balón antes de que llegue.", "C": "que el balón sale de la cancha.", "D": "que el árbitro detiene el juego."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la fuerza del pase debe ajustarse a la distancia?", "opciones": {"A": "Porque todos los pases deben ser fuertes.", "B": "Porque la distancia no importa.", "C": "Porque así se evita usar el pie de apoyo.", "D": "Porque un pase muy fuerte es difícil de controlar y uno muy suave puede ser cortado."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante pasa con el borde interno, pero el balón se desvía. Su pie de apoyo apunta hacia un lado. ¿Qué debe corregir?", "opciones": {"A": "Pasar con la punta del pie.", "B": "Golpear el balón por arriba.", "C": "Ubicar el pie de apoyo al lado del balón apuntando hacia el compañero.", "D": "Cerrar los ojos al pasar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Durante la conducción, un jugador mira solo el balón y choca con un rival. ¿Qué debe hacer?", "opciones": {"A": "Conducir más rápido.", "B": "Levantar la cabeza para ver el espacio y a los compañeros.", "C": "Dar toques más largos.", "D": "Detenerse siempre."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué la pierna debe acompañar el movimiento después del pase?", "opciones": {"A": "Porque así se ve más elegante.", "B": "Porque evita que el árbitro pite.", "C": "Porque no tiene ningún efecto.", "D": "Porque ayuda a dar dirección y precisión al balón."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En el drible, ¿hasta qué altura debe subir el bote?", "opciones": {"A": "No más arriba de la cintura.", "B": "Por encima de la cabeza.", "C": "Hasta los hombros.", "D": "Hasta donde alcance."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "Al soltar el pase de pecho, las manos:", "opciones": {"A": "se cierran en puño.", "B": "se quedan quietas en el pecho.", "C": "golpean el balón hacia abajo.", "D": "giran hacia afuera."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, ser «predecible» significa que:", "opciones": {"A": "el jugador es muy rápido.", "B": "el jugador nunca pierde el balón.", "C": "el rival puede adivinar fácilmente lo que vas a hacer.", "D": "el balón rebota mucho."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué es útil driblar con ambas manos?", "opciones": {"A": "Porque driblar con una sola mano es falta.", "B": "Porque permite proteger el balón según el lado donde esté el defensor.", "C": "Porque así el balón bota más alto.", "D": "Porque se cansa menos el brazo derecho."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un defensor está a la izquierda del jugador que dribla. ¿Con qué mano conviene driblar?", "opciones": {"A": "Con la mano derecha.", "B": "Con la mano izquierda.", "C": "Con las dos manos al tiempo.", "D": "Con la palma abierta."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un pase picado llega a los pies del compañero. ¿Qué debe corregir quien pasa?", "opciones": {"A": "Hacer que el balón rebote más cerca de sí mismo.", "B": "Hacer que el balón rebote más cerca del compañero.", "C": "Lanzarlo por encima de la cabeza.", "D": "Pasarlo con una sola mano."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero dribla golpeando el balón con la palma. Según el texto, ¿por qué no es correcto?", "opciones": {"A": "Porque la palma no puede tocar el balón según el reglamento.", "B": "Porque así el balón bota más bajo.", "C": "Porque es más rápido.", "D": "Porque el control se logra con la yema de los dedos y la muñeca."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "Según el texto, la bandeja es:", "opciones": {"A": "un lanzamiento en carrera muy cerca del aro.", "B": "un lanzamiento desde la línea de tres puntos.", "C": "un pase al compañero.", "D": "un tipo de drible."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, el «pie de impulso» es el que:", "opciones": {"A": "golpea el balón.", "B": "se queda en el aire.", "C": "empuja el cuerpo hacia arriba en el salto.", "D": "pisa la línea final."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el cuerpo va ligeramente sobre el balón al rematar?", "opciones": {"A": "Para que el balón no se eleve demasiado y vaya hacia el arco.", "B": "Para patear más débil.", "C": "Para caer al suelo.", "D": "Para evitar al portero."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un estudiante ataca por la derecha para hacer bandeja. ¿Con qué pie debe dar el segundo paso e impulsarse?", "opciones": {"A": "Con el pie derecho.", "B": "Con el pie izquierdo.", "C": "Con los dos pies juntos.", "D": "No debe dar pasos."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué es más importante en el remate según el texto?", "opciones": {"A": "La fuerza máxima, sin mirar.", "B": "Rematar siempre al centro.", "C": "La precisión, mirando la posición del portero.", "D": "Rematar con la punta del pie."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Relacionando las tres lecturas, ¿qué tienen en común la conducción, el drible, el pase y el lanzamiento bien ejecutados?", "opciones": {"A": "Dependen solo de la fuerza.", "B": "Se hacen sin mirar a los compañeros.", "C": "No necesitan práctica.", "D": "Requieren control del balón, buena posición del cuerpo y mirar el juego para decidir."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g8-p1-quiz1", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Quiz 1 — Coordinación, equilibrio y ritmo en el deporte (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Coordinación, equilibrio y ritmo en el deporte", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En el deporte, la coordinación permite que los músculos actúen en el momento justo y con la fuerza necesaria. Un saque de voleibol exige coordinar el lanzamiento del balón con la mano que golpea; una bandeja de baloncesto, coordinar los pasos, el salto y el brazo. Cuando un movimiento está bien coordinado, se gasta menos energía y se cometen menos errores.<br><br>El equilibrio permite mantener el control del cuerpo al saltar, al caer o al recibir un contacto. Un jugador con buen equilibrio aterriza sin perder la posición y puede seguir jugando de inmediato. El ritmo es la organización de los movimientos en el tiempo: la cadencia de los pasos antes de un salto, la secuencia de saltos con la cuerda o el momento exacto para golpear el balón. La escalera de agilidad, los saltos combinados y la cuerda con música entrenan estas tres capacidades a la vez, porque obligan a mover los pies con orden, precisión y control."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, un saque de voleibol exige coordinar:", "opciones": {"A": "los pasos con la respiración únicamente.", "B": "el lanzamiento del balón con la mano que golpea.", "C": "la mirada con el árbitro.", "D": "el pie de apoyo con el aro."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué permite un buen equilibrio a un jugador, según el texto?", "opciones": {"A": "Aterrizar sin perder la posición y seguir jugando.", "B": "Saltar sin usar las piernas.", "C": "Correr sin mover los brazos.", "D": "Evitar todo contacto con el balón."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el ritmo es:", "opciones": {"A": "la fuerza máxima de un salto.", "B": "la distancia entre dos jugadores.", "C": "la organización de los movimientos en el tiempo.", "D": "el número de jugadores en la cancha."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «cadencia» se refiere a:", "opciones": {"A": "la caída del jugador al piso.", "B": "el color del uniforme.", "C": "el tamaño de la cancha.", "D": "la repetición regular de los pasos en el tiempo."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué un movimiento bien coordinado gasta menos energía?", "opciones": {"A": "Porque los músculos actúan en el momento justo y sin esfuerzos de más.", "B": "Porque se hace sin moverse.", "C": "Porque elimina la necesidad de entrenar.", "D": "Porque solo intervienen los brazos."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador pierde el balón en el saque porque lo lanza demasiado alto y golpea tarde. ¿Qué debe mejorar?", "opciones": {"A": "La resistencia aeróbica.", "B": "La coordinación entre el lanzamiento y el golpe.", "C": "La flexibilidad de las piernas.", "D": "El número de pasos de la bandeja."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Qué ejercicio entrena al mismo tiempo coordinación, equilibrio y ritmo?", "opciones": {"A": "Permanecer sentado.", "B": "Leer el reglamento.", "C": "Lanzar el balón al aire sin mirarlo.", "D": "La escalera de agilidad."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Después de un bloqueo, un jugador cae y tarda en reincorporarse al juego. ¿Qué capacidad le conviene mejorar?", "opciones": {"A": "La lateralidad.", "B": "La memoria.", "C": "El equilibrio.", "D": "La flexibilidad del cuello."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, una bandeja de baloncesto exige coordinar:", "opciones": {"A": "los pasos, el salto y el brazo.", "B": "solo el brazo.", "C": "solo la mirada.", "D": "la voz y las manos."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué los ejercicios de cuerda con música son útiles para un deportista?", "opciones": {"A": "Porque reemplazan los partidos.", "B": "Porque obligan a mover los pies con orden, precisión y control en el tiempo.", "C": "Porque solo sirven para bailar.", "D": "Porque no requieren concentración."}}]}, {"id": "2027-g8-p1-quiz2", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Quiz 2 — Reglamento de voleibol y baloncesto (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Rotación, faltas, violaciones y puntuación", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En el voleibol, cada equipo tiene seis jugadores en la cancha. Cuando un equipo recupera el derecho de sacar, sus jugadores rotan una posición en el sentido de las manecillas del reloj. Cada equipo puede tocar el balón hasta tres veces antes de pasarlo, sin contar el toque del bloqueo, y un jugador no puede tocarlo dos veces seguidas. Son faltas el doble toque, la retención del balón, el toque de red y pasar por debajo de la red invadiendo el campo contrario. Se gana un punto en cada jugada; un set se gana al llegar a 25 puntos con al menos dos de diferencia, y el quinto set se juega a 15.<br><br>En el baloncesto se distingue entre violaciones y faltas. Las violaciones son infracciones a las reglas del balón o del tiempo, como los pasos, el doble drible o permanecer más de tres segundos en la zona restringida del rival; se sancionan con la pérdida del balón. Las faltas personales son contactos ilegales con un rival, como empujar, sujetar o golpear. Una canasta vale dos o tres puntos según la distancia, y un tiro libre, un punto."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuántos jugadores tiene cada equipo de voleibol en la cancha?", "opciones": {"A": "Cinco.", "B": "Cuatro.", "C": "Seis.", "D": "Siete."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué sentido rotan los jugadores de voleibol?", "opciones": {"A": "En sentido contrario a las manecillas.", "B": "En el sentido de las manecillas del reloj.", "C": "De adelante hacia atrás sin orden.", "D": "No rotan."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿A cuántos puntos se juega un set de voleibol, excepto el quinto?", "opciones": {"A": "A 15, sin diferencia.", "B": "A 21, con un punto de diferencia.", "C": "A 30.", "D": "A 25, con al menos dos de diferencia."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, una «violación» en baloncesto es:", "opciones": {"A": "una infracción a las reglas del balón o del tiempo.", "B": "un contacto ilegal con un rival.", "C": "una canasta de tres puntos.", "D": "un cambio de jugador."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el toque del bloqueo no se cuenta entre los tres toques del equipo?", "opciones": {"A": "Porque el bloqueo es falta.", "B": "Porque el reglamento lo considera una acción defensiva aparte.", "C": "Porque nunca se toca el balón al bloquear.", "D": "Porque así se acaba la jugada."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador de baloncesto se queda cuatro segundos dentro de la zona restringida del rival. ¿Qué ocurre?", "opciones": {"A": "Recibe una falta personal y tiros libres.", "B": "Su equipo gana dos puntos.", "C": "Comete violación de tres segundos y su equipo pierde el balón.", "D": "No pasa nada."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "En voleibol, un jugador toca la red durante una jugada. ¿Qué se sanciona?", "opciones": {"A": "Toque de red: punto para el rival.", "B": "Rotación del propio equipo.", "C": "Tiro libre.", "D": "Nada, si el balón pasó."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Un jugador empuja a un rival que va a lanzar. ¿Qué tipo de infracción es?", "opciones": {"A": "Una violación de pasos.", "B": "Un doble drible.", "C": "Una violación de tres segundos.", "D": "Una falta personal."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuánto vale un tiro libre en baloncesto?", "opciones": {"A": "Dos puntos.", "B": "Un punto.", "C": "Tres puntos.", "D": "Medio punto."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué es útil distinguir entre violaciones y faltas personales?", "opciones": {"A": "Porque son exactamente lo mismo.", "B": "Porque las faltas no se sancionan.", "C": "Porque cada una tiene una sanción distinta y ayuda a arbitrar con justicia.", "D": "Porque solo importan a los entrenadores."}}]}, {"id": "2027-g8-p1-taller", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Taller escrito digital — Reglamentación y señales arbitrales (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Señales arbitrales del voleibol", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El árbitro de voleibol usa el silbato y señales con los brazos para que jugadores y público entiendan sus decisiones. Para indicar que el balón cayó dentro de la cancha, extiende el brazo y los dedos apuntando hacia el piso. Si cayó fuera, levanta los antebrazos en posición vertical con las palmas de las manos hacia su cuerpo. Para indicar qué equipo sacará, extiende el brazo hacia ese lado.<br><br>Algunas faltas tienen señales con los dedos: levantar dos dedos separados indica doble toque, y levantar cuatro dedos indica que el equipo tocó el balón cuatro veces. Para la retención, el árbitro levanta lentamente el antebrazo con la palma hacia arriba. Para el toque de red, señala la red con la mano del lado del infractor. Conocer estas señales ayuda a entender el juego y a respetar las decisiones."}, {"id": 2, "titulo": "Señales arbitrales del baloncesto", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "En el baloncesto, el árbitro detiene el reloj con el silbato y luego muestra la señal. Para los pasos, gira los puños uno alrededor del otro frente al cuerpo. Para el doble drible, hace con las palmas un movimiento de botar alternando las manos. La violación de tres segundos se indica con el brazo extendido mostrando tres dedos.<br><br>Una falta personal se señala levantando el puño cerrado; después, el árbitro indica el número del jugador y el tipo de falta. Cuando un jugador intenta un lanzamiento desde detrás de la línea de tres puntos, el árbitro levanta un brazo con tres dedos extendidos, y si la canasta entra, levanta los dos brazos. Las señales permiten que la mesa de control anote correctamente y que todos sepan qué se sancionó."}, {"id": 3, "titulo": "Ser árbitro estudiantil", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "En la clase, los estudiantes también arbitran. Un buen árbitro conoce el reglamento, se ubica donde puede ver bien la jugada, pita con decisión y muestra la señal con claridad. Debe ser imparcial: aplicar la misma regla a los dos equipos, sin importar si juegan sus amigos.<br><br>El árbitro trabaja con una planilla donde se anotan los puntos, las faltas y los cambios. Si se equivoca, puede reconocerlo y corregir con respeto. Los jugadores, por su parte, aceptan las decisiones sin discutir de forma agresiva; si tienen una duda, la expresa el capitán con calma. Arbitrar ayuda a comprender mejor las reglas y a valorar el trabajo de quienes dirigen los partidos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "En voleibol, ¿cómo indica el árbitro que el balón cayó dentro?", "opciones": {"A": "Extiende el brazo y los dedos apuntando hacia el piso.", "B": "Levanta los antebrazos con las palmas hacia su cuerpo.", "C": "Levanta dos dedos.", "D": "Gira los puños."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué significa que el árbitro levante cuatro dedos en voleibol?", "opciones": {"A": "Que el equipo ganó cuatro puntos.", "B": "Que el equipo tocó el balón cuatro veces.", "C": "Que quedan cuatro minutos.", "D": "Que hubo cuatro cambios."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «infractor» se refiere a:", "opciones": {"A": "el árbitro principal.", "B": "el equipo que va ganando.", "C": "el jugador o equipo que cometió la falta.", "D": "el público."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el árbitro usa señales además del silbato?", "opciones": {"A": "Porque el silbato no suena.", "B": "Para alargar el partido.", "C": "Porque el reglamento prohíbe hablar a los jugadores.", "D": "Para que jugadores y público entiendan qué decidió."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "El árbitro de voleibol levanta lentamente el antebrazo con la palma hacia arriba. ¿Qué sancionó?", "opciones": {"A": "Doble toque.", "B": "Retención del balón.", "C": "Toque de red.", "D": "Balón fuera."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "El balón cae fuera de la cancha. ¿Qué señal debe hacer el árbitro?", "opciones": {"A": "Apuntar al piso con el brazo extendido.", "B": "Mostrar dos dedos.", "C": "Levantar los antebrazos verticales con las palmas hacia su cuerpo.", "D": "Levantar el puño cerrado."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué conocer las señales ayuda a respetar las decisiones del árbitro?", "opciones": {"A": "Porque así se puede discutir mejor.", "B": "Porque las señales cambian el resultado.", "C": "Porque solo los árbitros deben conocerlas.", "D": "Porque al entender qué se sancionó se evitan discusiones innecesarias."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En baloncesto, ¿qué señal indica pasos?", "opciones": {"A": "Girar los puños uno alrededor del otro frente al cuerpo.", "B": "Levantar el puño cerrado.", "C": "Mostrar tres dedos con el brazo extendido.", "D": "Levantar los dos brazos."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cómo se señala una falta personal?", "opciones": {"A": "Girando los puños.", "B": "Apuntando al piso.", "C": "Haciendo la señal de botar.", "D": "Levantando el puño cerrado."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, la «mesa de control» es:", "opciones": {"A": "la mesa donde se guardan los balones.", "B": "el lugar donde se anotan los puntos y las faltas.", "C": "el banco de suplentes.", "D": "la zona restringida."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué el árbitro detiene el reloj antes de mostrar la señal?", "opciones": {"A": "Para terminar el partido.", "B": "Para dar más tiempo al equipo que va ganando.", "C": "Para que el tiempo no corra mientras se aplica la sanción.", "D": "Porque las señales solo se hacen al final."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un jugador lanza desde detrás de la línea de tres puntos y encesta. ¿Qué señal corresponde?", "opciones": {"A": "Levantar los dos brazos después de indicar el intento con tres dedos.", "B": "Levantar el puño cerrado.", "C": "Girar los puños.", "D": "Mostrar dos dedos."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "El árbitro hace con las palmas un movimiento de botar alternando las manos. ¿Qué sancionó?", "opciones": {"A": "Tres segundos.", "B": "Falta personal.", "C": "Doble drible.", "D": "Canasta de tres puntos."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué ocurriría si el árbitro no indicara el número del jugador que hizo la falta?", "opciones": {"A": "No cambiaría nada.", "B": "El partido terminaría.", "C": "El jugador ganaría puntos.", "D": "La mesa de control no podría anotar bien las faltas de cada jugador."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "Según el texto, ¿qué se anota en la planilla?", "opciones": {"A": "Los puntos, las faltas y los cambios.", "B": "Solo el nombre del árbitro.", "C": "Las notas del periodo.", "D": "El clima del día."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, pitar «con decisión» significa:", "opciones": {"A": "con mucha fuerza en los pulmones.", "B": "con seguridad y sin dudar.", "C": "solo cuando lo piden los jugadores.", "D": "después de consultar al público."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué un buen árbitro se ubica donde puede ver bien la jugada?", "opciones": {"A": "Para tomar decisiones correctas con base en lo que observa.", "B": "Para estar cerca de sus amigos.", "C": "Para no tener que moverse.", "D": "Para tapar la vista del público."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un jugador no está de acuerdo con una decisión. ¿Qué es lo correcto según el texto?", "opciones": {"A": "Que todos rodeen al árbitro gritando.", "B": "Abandonar el partido.", "C": "Que el capitán exprese la duda con calma.", "D": "Ignorar al árbitro y seguir jugando."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué aprende un estudiante al arbitrar?", "opciones": {"A": "A favorecer a su equipo.", "B": "A comprender mejor las reglas y a valorar el trabajo de quien dirige.", "C": "A evitar las reglas.", "D": "Nada útil para el juego."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Relacionando las tres lecturas, ¿qué se necesita para un partido bien dirigido?", "opciones": {"A": "Pitar solo las faltas del equipo rival.", "B": "Usar señales inventadas por cada árbitro.", "C": "Dejar que los jugadores decidan todo.", "D": "Conocer el reglamento, usar las señales correctas y arbitrar con imparcialidad y respeto."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g9-p1-quiz1", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Quiz 1 — Principios tácticos de ataque y defensa (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Atacar y defender con inteligencia", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En los deportes de conjunto, como el microfútbol, el equipo que tiene el balón ataca y el que no lo tiene defiende. El ataque sigue tres principios: conservar la posesión del balón, progresar hacia la meta rival y finalizar con un remate o lanzamiento. Para lograrlo, los jugadores ocupan el espacio con amplitud (abriéndose hacia los costados) y profundidad (ubicándose a distintas alturas de la cancha), ofrecen apoyos cerca de quien tiene el balón y hacen desmarques, es decir, se mueven para quedar libres de su marcador.<br><br>La defensa también tiene principios: recuperar el balón, impedir que el rival progrese y proteger la propia meta. Para ello se usa el marcaje, que es vigilar de cerca a un rival; las coberturas, que consisten en ayudar al compañero que fue superado; y el repliegue, que es regresar rápido a la propia zona cuando se pierde el balón. En los juegos de posesión, como los rondos y el 4 contra 4, se practican estos principios."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuáles son los tres principios del ataque?", "opciones": {"A": "Conservar la posesión, progresar hacia la meta y finalizar.", "B": "Marcar, cubrir y replegar.", "C": "Saltar, correr y lanzar.", "D": "Defender, esperar y pitar."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué es el repliegue?", "opciones": {"A": "Abrirse hacia los costados.", "B": "Rematar al arco.", "C": "Pasar el balón hacia adelante.", "D": "Regresar rápido a la propia zona cuando se pierde el balón."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la amplitud consiste en:", "opciones": {"A": "quedarse todos en el centro.", "B": "abrirse hacia los costados de la cancha.", "C": "vigilar de cerca a un rival.", "D": "regresar a la propia zona."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, un «desmarque» es:", "opciones": {"A": "una falta del defensor.", "B": "el saque inicial del partido.", "C": "el movimiento para quedar libre del marcador.", "D": "un cambio de jugador."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el equipo atacante debe ocupar el espacio con amplitud y profundidad?", "opciones": {"A": "Porque así se cansa menos.", "B": "Porque el reglamento lo exige.", "C": "Para que el balón salga de la cancha.", "D": "Porque así abre la defensa rival y crea líneas de pase."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un defensor es superado por el rival y un compañero sale a ayudarlo. ¿Qué principio defensivo aplica?", "opciones": {"A": "La cobertura.", "B": "El desmarque.", "C": "La finalización.", "D": "La amplitud."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador tiene el balón presionado y sus compañeros están lejos. ¿Qué deben hacer ellos?", "opciones": {"A": "Quedarse quietos esperando.", "B": "Salir de la cancha.", "C": "Acercarse para ofrecerle apoyos.", "D": "Pedir cambio."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Un equipo pierde el balón y todos se quedan en el ataque. ¿Qué riesgo corre?", "opciones": {"A": "Que el partido se detenga.", "B": "Que el rival ataque con espacio libre hacia su meta.", "C": "Que el árbitro pite falta.", "D": "Ninguno, porque ya atacaron."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué tipo de juegos se practican estos principios, según el texto?", "opciones": {"A": "En carreras de 100 metros.", "B": "En ejercicios de flexibilidad.", "C": "En lanzamientos de bala.", "D": "En juegos de posesión como rondos y 4 contra 4."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el texto dice atacar y defender «con inteligencia»?", "opciones": {"A": "Porque se trata de tomar buenas decisiones en equipo, no solo de correr más.", "B": "Porque solo juegan los mejores estudiantes.", "C": "Porque hay que memorizar el reglamento.", "D": "Porque la fuerza no importa en ningún caso."}}]}, {"id": "2027-g9-p1-quiz2", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Quiz 2 — Sistemas de juego y reglamento (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Sistemas de juego en microfútbol y voleibol", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Un sistema de juego es la forma en que un equipo distribuye a sus jugadores en la cancha. En el microfútbol, donde juegan cinco por equipo, se nombra sin contar al portero. En el sistema 2-2, o cuadrado, dos jugadores defienden y dos atacan; es equilibrado y fácil de aprender. En el 1-2-1, o rombo, hay un jugador atrás, dos por los costados y uno adelante, lo que da amplitud y profundidad al ataque. Ningún sistema es mejor en todos los casos: se elige según las características del equipo y del rival.<br><br>En el voleibol, el sistema indica cuántos atacantes y cuántos armadores tiene el equipo. En el 4-2 hay cuatro atacantes y dos armadores, ubicados en posiciones opuestas; es común en equipos que están aprendiendo. En el 5-1 hay cinco atacantes y un solo armador, que organiza el juego desde cualquier posición. En ambos deportes, el sistema solo funciona si los jugadores respetan el reglamento: en voleibol, tres toques por equipo y rotación en el sentido de las manecillas del reloj; en microfútbol, juego sin contacto violento y saques correctos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, un sistema de juego es:", "opciones": {"A": "el reglamento del deporte.", "B": "el número de puntos de un set.", "C": "la forma en que un equipo distribuye a sus jugadores en la cancha.", "D": "el uniforme del equipo."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "En el sistema 2-2 de microfútbol:", "opciones": {"A": "dos jugadores defienden y dos atacan.", "B": "todos defienden.", "C": "uno defiende y tres atacan.", "D": "no hay portero."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "En el sistema 5-1 de voleibol hay:", "opciones": {"A": "cinco armadores y un atacante.", "B": "cinco atacantes y un armador.", "C": "cuatro atacantes y dos armadores.", "D": "seis armadores."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, un «armador» es el jugador que:", "opciones": {"A": "solo saca.", "B": "solo bloquea.", "C": "arbitra el partido.", "D": "organiza el juego y prepara el balón para el ataque."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto dice que ningún sistema es mejor en todos los casos?", "opciones": {"A": "Porque se elige según las características del propio equipo y del rival.", "B": "Porque todos los sistemas son iguales.", "C": "Porque los sistemas no sirven.", "D": "Porque el árbitro decide el sistema."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un equipo de microfútbol quiere más amplitud y profundidad en el ataque. ¿Qué sistema le conviene?", "opciones": {"A": "El 2-2 con todos atrás.", "B": "Jugar sin portero.", "C": "El 1-2-1 o rombo.", "D": "El 4-2 de voleibol."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un equipo de voleibol que está aprendiendo quiere tener dos armadores. ¿Qué sistema debe usar?", "opciones": {"A": "El 5-1.", "B": "El 2-2.", "C": "El 1-2-1.", "D": "El 4-2."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el 2-2 es fácil de aprender?", "opciones": {"A": "Porque no tiene defensa.", "B": "Porque reparte las tareas de forma simple y equilibrada.", "C": "Porque no se mueve nadie.", "D": "Porque no tiene reglas."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, en voleibol los jugadores rotan:", "opciones": {"A": "en el sentido de las manecillas del reloj.", "B": "en sentido contrario a las manecillas.", "C": "solo cuando lo pide el capitán.", "D": "al final de cada set únicamente."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un equipo tiene un buen sistema, pero sus jugadores cometen muchas faltas. Según el texto:", "opciones": {"A": "el sistema compensa las faltas.", "B": "las faltas no afectan el juego.", "C": "el sistema no funciona si no se respeta el reglamento.", "D": "conviene cambiar de deporte."}}]}, {"id": "2027-g9-p1-taller", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Taller escrito digital — Diseño de una jugada o estrategia (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Táctica, estrategia y jugada", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Aunque se usan como sinónimos, estrategia y táctica no son lo mismo. La estrategia es el plan que el equipo prepara antes del partido: cómo va a atacar, cómo va a defender y qué hará en ciertas situaciones. La táctica son las decisiones que se toman durante el juego para aplicar ese plan según lo que hace el rival.<br><br>Una jugada es una secuencia de acciones acordada de antemano para resolver una situación concreta, como un saque de banda en microfútbol o una recepción con ataque por la zona 4 en voleibol. Una buena jugada tiene un objetivo claro, asigna una tarea a cada jugador y es sencilla de ejecutar. Si es demasiado complicada, el equipo se confunde y la pierde."}, {"id": 2, "titulo": "La pizarra táctica", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Para diseñar una jugada se usa la pizarra táctica, un dibujo de la cancha visto desde arriba. En la clase usamos estos símbolos: los jugadores propios se marcan con círculos numerados y los rivales con una X; una flecha de línea continua indica el desplazamiento de un jugador sin balón, una flecha de línea discontinua indica un pase, y una línea ondulada indica la conducción con el balón.<br><br>La jugada se dibuja por pasos, numerando el orden de las acciones: primero el pase, luego el desmarque, después el remate. Cada jugador debe poder mirar la pizarra y saber qué le corresponde hacer. Una pizarra clara evita malentendidos y permite explicar la jugada a todo el equipo en poco tiempo."}, {"id": 3, "titulo": "Ensayar, evaluar y ajustar", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Una jugada dibujada todavía no está terminada: hay que ensayarla. Primero se practica despacio y sin oposición para aprender los movimientos; luego con oposición pasiva, y finalmente en situación de juego. Durante el ensayo, el capitán y los compañeros se comunican con señales o palabras clave para iniciar la jugada en el momento justo.<br><br>Después de usarla en un partido, el equipo evalúa: ¿se cumplió el objetivo? ¿Cada jugador hizo su tarea? ¿Qué hizo el rival para impedirla? Con esas respuestas se ajusta la jugada. Evaluar no es buscar culpables, sino mejorar el plan entre todos. Por eso el liderazgo de los capitanes y la escucha de todo el equipo son tan importantes como la técnica."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la estrategia es:", "opciones": {"A": "el plan que el equipo prepara antes del partido.", "B": "la decisión que se toma en medio del juego.", "C": "el dibujo de la cancha.", "D": "el uniforme del equipo."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué caracteriza a una buena jugada?", "opciones": {"A": "Es muy complicada para sorprender.", "B": "Solo la conoce el capitán.", "C": "Tiene un objetivo claro, una tarea para cada jugador y es sencilla.", "D": "Cambia en cada intento sin orden."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la expresión «de antemano» significa:", "opciones": {"A": "al final del partido.", "B": "antes de que ocurra.", "C": "durante el descanso.", "D": "sin planearlo."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué una jugada demasiado complicada puede fallar?", "opciones": {"A": "Porque el árbitro la prohíbe.", "B": "Porque el rival la conoce siempre.", "C": "Porque las jugadas sencillas no existen.", "D": "Porque el equipo se confunde y no la ejecuta bien."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "En pleno partido, el rival empieza a marcar muy cerca y el equipo decide pasar más rápido. ¿Qué está aplicando?", "opciones": {"A": "La estrategia previa.", "B": "La pizarra táctica.", "C": "La táctica.", "D": "Un sistema de voleibol."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cuál es un ejemplo de jugada según el texto?", "opciones": {"A": "Un calentamiento general.", "B": "Una secuencia acordada para un saque de banda.", "C": "Una carrera de resistencia.", "D": "Un estiramiento final."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué conviene diferenciar estrategia y táctica?", "opciones": {"A": "Porque son exactamente lo mismo.", "B": "Porque solo importa la estrategia.", "C": "Porque la táctica no se puede aprender.", "D": "Porque permite planear antes y también adaptarse durante el juego."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En la pizarra que usamos en clase, ¿cómo se marcan los rivales?", "opciones": {"A": "Con una X.", "B": "Con círculos numerados.", "C": "Con flechas.", "D": "Con líneas onduladas."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué indica una flecha de línea discontinua?", "opciones": {"A": "La conducción con el balón.", "B": "El desplazamiento sin balón.", "C": "La ubicación del árbitro.", "D": "Un pase."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, un «malentendido» es:", "opciones": {"A": "una jugada que sale perfecta.", "B": "una falta del árbitro.", "C": "una confusión porque algo se entendió de forma equivocada.", "D": "un tipo de pase."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué se numeran las acciones de la jugada en la pizarra?", "opciones": {"A": "Para que la pizarra se vea más llena.", "B": "Para que todos sepan en qué orden ocurre cada acción.", "C": "Porque el reglamento lo exige.", "D": "Para que el rival no la entienda."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un jugador debe conducir el balón por la banda. ¿Qué símbolo se dibuja?", "opciones": {"A": "Una línea ondulada.", "B": "Una flecha de línea continua.", "C": "Una flecha de línea discontinua.", "D": "Una X."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "El número 3 debe correr al espacio libre sin balón. ¿Cómo se representa?", "opciones": {"A": "Con una X sobre el número 3.", "B": "Con una flecha de línea continua desde el círculo 3.", "C": "Con una línea ondulada.", "D": "Con una flecha discontinua hacia el arco."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué ventaja tiene una pizarra clara para el equipo?", "opciones": {"A": "Reemplaza el entrenamiento.", "B": "Garantiza ganar el partido.", "C": "Solo sirve para el profesor.", "D": "Permite explicar la jugada rápido y evitar confusiones."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "Según el texto, ¿cómo se empieza a ensayar una jugada?", "opciones": {"A": "Despacio y sin oposición.", "B": "En partido oficial directamente.", "C": "Con oposición total desde el inicio.", "D": "Sin explicar la pizarra."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, la «oposición pasiva» es cuando:", "opciones": {"A": "no hay rivales en la cancha.", "B": "el rival juega al máximo.", "C": "hay rivales presentes, pero sin presionar con toda la intensidad.", "D": "el árbitro detiene la jugada."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Para qué sirven las señales o palabras clave durante el ensayo?", "opciones": {"A": "Para iniciar la jugada en el momento justo y de forma coordinada.", "B": "Para distraer al árbitro.", "C": "Para que el rival se entere.", "D": "Para terminar el partido."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "La jugada falló porque un jugador no se desmarcó a tiempo. ¿Qué debe hacer el equipo?", "opciones": {"A": "Culparlo frente a todos.", "B": "Evaluar con él lo ocurrido y ajustar la jugada o su tarea.", "C": "Borrar la jugada sin analizarla.", "D": "Sacarlo del equipo."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿por qué el liderazgo y la escucha son tan importantes como la técnica?", "opciones": {"A": "Porque la técnica no importa.", "B": "Porque el capitán juega solo.", "C": "Porque las jugadas se mejoran entre todos con buena comunicación.", "D": "Porque así se evita entrenar."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Relacionando las tres lecturas, ¿cuál es el proceso completo para una jugada eficaz?", "opciones": {"A": "Improvisarla en cada partido.", "B": "Dibujarla y no ensayarla nunca.", "C": "Copiar la jugada de otro equipo sin entenderla.", "D": "Planearla con un objetivo, representarla con claridad en la pizarra, ensayarla y ajustarla tras evaluarla."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g10-p1-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 1", "titulo": "Quiz — Fútbol: Reglas de Juego básicas (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Las Reglas de Juego", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las Reglas de Juego del fútbol las establece la IFAB (International Football Association Board) y las aplica la FIFA en todo el mundo. Cada equipo tiene once jugadores, uno de ellos el guardameta, y un partido no puede comenzar si alguno tiene menos de siete. El partido dura dos tiempos de 45 minutos, más el tiempo que el árbitro añada por pérdidas de tiempo.<br><br>Se concede un tiro penal cuando un jugador comete una falta que se sanciona con tiro libre directo dentro de su propia área penal; el penal se cobra desde 11 metros. Las faltas más leves se sancionan con tiro libre indirecto, en el que el gol solo es válido si el balón toca a otro jugador antes de entrar. La tarjeta amarilla es una amonestación; la roja es una expulsión, y el jugador expulsado no puede ser reemplazado.<br><br>Un jugador está en posición de fuera de juego si, en el momento en que un compañero juega el balón, está en la mitad del campo rival y más cerca de la línea de meta que el balón y que el penúltimo adversario. Estar en esa posición no es una infracción por sí mismo: solo se sanciona si el jugador participa en la jugada. Además, no hay fuera de juego si el jugador recibe directamente de un saque de meta, de banda o de esquina."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué organismo establece las Reglas de Juego del fútbol?", "opciones": {"A": "La IFAB.", "B": "El Comité Olímpico.", "C": "La FIVB.", "D": "La FIBA."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es el número mínimo de jugadores para iniciar un partido?", "opciones": {"A": "Siete por equipo.", "B": "Once por equipo.", "C": "Cinco por equipo.", "D": "Nueve por equipo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Desde qué distancia se cobra el tiro penal?", "opciones": {"A": "6 metros.", "B": "11 metros.", "C": "16 metros.", "D": "9 metros."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En un tiro libre «indirecto», el gol es válido solo si:", "opciones": {"A": "se patea con el pie izquierdo.", "B": "se cobra desde fuera del área.", "C": "el balón toca a otro jugador antes de entrar.", "D": "el portero no se mueve."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe tarjeta roja en el minuto 30. ¿Qué ocurre con su equipo?", "opciones": {"A": "Pierde automáticamente el partido.", "B": "Sigue jugando con un jugador menos, porque el expulsado no puede ser reemplazado.", "C": "Puede reemplazarlo con un suplente.", "D": "Debe cobrar un penal en contra."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el árbitro añade tiempo al final de cada tiempo?", "opciones": {"A": "Para que los jugadores descansen.", "B": "Porque el reglamento exige 50 minutos.", "C": "Para compensar el tiempo perdido durante el partido.", "D": "Para que el equipo que pierde pueda empatar."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "Para estar en posición de fuera de juego, el jugador debe estar:", "opciones": {"A": "detrás del balón.", "B": "en la mitad rival, más cerca de la línea de meta que el balón y que el penúltimo adversario.", "C": "en su propia mitad del campo.", "D": "a la misma altura del penúltimo adversario."}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un delantero recibe directamente de un saque de banda estando detrás de todos los defensores. ¿Hay fuera de juego?", "opciones": {"A": "Sí, siempre que esté detrás de los defensores.", "B": "Solo si el árbitro lo considera peligroso.", "C": "Sí, si el balón llega por el aire.", "D": "No, porque desde un saque de banda no hay fuera de juego."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "Un jugador en posición de fuera de juego que no participa en la jugada:", "opciones": {"A": "no comete infracción.", "B": "recibe tarjeta amarilla.", "C": "debe salir del campo.", "D": "siempre es sancionado."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Para qué sirven, en general, las Reglas de Juego?", "opciones": {"A": "Para que los árbitros decidan el resultado.", "B": "Para que el fútbol sea más lento.", "C": "Para que gane el equipo con más jugadores.", "D": "Para que el partido sea justo, seguro y igual para todos."}}], "modalidad": "Quiz"}, {"id": "2027-g10-p1", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Fútbol: reglamento, táctica y ritmo de juego (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Faltas, sanciones y juego limpio", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El árbitro sanciona con tiro libre directo las acciones que un jugador comete contra un adversario de manera imprudente, temeraria o con uso de fuerza excesiva: cargar, empujar, golpear, poner una zancadilla o sujetar a un rival, entre otras. También es tiro libre directo tocar el balón deliberadamente con la mano o el brazo, excepto el guardameta dentro de su área. Una acción imprudente se castiga solo con la falta; una temeraria, con tarjeta amarilla; y una con fuerza excesiva, con tarjeta roja.<br><br>El árbitro puede aplicar la «ventaja»: si después de una falta el equipo que la sufrió sigue teniendo una buena opción de ataque, deja continuar el juego en lugar de detenerlo, y puede amonestar al infractor cuando el balón quede fuera de juego. El reglamento busca proteger la integridad física de los jugadores y premiar a quien juega con limpieza. Por eso, actitudes como devolver el balón al rival cuando se detuvo el juego por una lesión no están escritas como obligación, pero hacen parte del espíritu del fútbol."}, {"id": 2, "titulo": "Sistemas tácticos y transiciones", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Un sistema táctico es la forma en que un equipo distribuye a sus jugadores en el campo. Se nombra con números que van desde la defensa hasta el ataque, sin contar al portero, aunque a veces se escribe el 1 inicial para incluirlo. En el 1-4-4-2 hay cuatro defensas, cuatro mediocampistas y dos delanteros; es un sistema equilibrado. En el 1-4-3-3 hay tres mediocampistas y tres delanteros, lo que favorece el juego por las bandas y la presión en campo rival.<br><br>El fútbol moderno se piensa en cuatro momentos: ataque organizado, defensa organizada y dos transiciones. La transición ataque-defensa ocurre cuando el equipo pierde el balón: los jugadores más cercanos presionan de inmediato para recuperarlo o retrasar al rival, mientras el resto vuelve a su posición. La transición defensa-ataque ocurre al recuperarlo: se busca salir rápido hacia el arco rival antes de que la defensa contraria se organice. Los equipos que dominan las transiciones suelen anotar más goles, porque aprovechan los momentos en que el rival está desordenado."}, {"id": 3, "titulo": "El ritmo del juego y la expresión del jugador", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "Un partido de fútbol tiene ritmo, como una pieza musical. Hay momentos de pausa, en los que el equipo se pasa el balón con calma para ordenarse, y momentos de aceleración, en los que un pase vertical, un cambio de frente o un regate rompen la defensa. Los jugadores inteligentes saben «cambiar el ritmo»: alternan pases cortos y largos, lentos y rápidos, para que el rival no adivine la siguiente acción. El cambio de ritmo también es individual: un delantero que conduce despacio y de repente acelera puede superar a un defensor más rápido que él.<br><br>El fútbol también es expresión corporal y cultural. Las celebraciones, los cantos de la hinchada y los estilos de juego de cada región muestran identidades diferentes. En Colombia, por ejemplo, se suele destacar el juego técnico y de toque. Valorar esas expresiones implica respetar al rival, a los árbitros y a las hinchadas contrarias: la diversidad hace más rica la cultura del fútbol, y la violencia en los estadios la destruye."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál de estas acciones se sanciona con tiro libre directo?", "opciones": {"A": "Estar en posición de fuera de juego sin participar.", "B": "Poner una zancadilla a un adversario de manera imprudente.", "C": "Celebrar un gol con el público.", "D": "Pedir el balón en voz alta."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Una acción temeraria contra un rival se sanciona con:", "opciones": {"A": "saque de banda.", "B": "tarjeta roja siempre.", "C": "tiro libre directo y tarjeta amarilla.", "D": "solo tiro libre indirecto."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, aplicar la «ventaja» significa:", "opciones": {"A": "dejar seguir el juego si el equipo que sufrió la falta tiene una buena opción de ataque.", "B": "permitir que un equipo tenga un jugador más.", "C": "dar un penal al equipo que va perdiendo.", "D": "añadir tiempo al final del partido."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un defensor golpea a un rival con fuerza excesiva en una disputa. ¿Qué debe hacer el árbitro?", "opciones": {"A": "Sancionar tiro libre indirecto.", "B": "Sancionar tiro libre directo y mostrar tarjeta roja.", "C": "Dejar seguir el juego sin sanción.", "D": "Mostrar solo tarjeta amarilla."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Cuál es el propósito principal del reglamento sobre faltas?", "opciones": {"A": "Proteger la integridad física de los jugadores y premiar el juego limpio.", "B": "Aumentar el número de tarjetas.", "C": "Hacer que los partidos tengan menos goles.", "D": "Favorecer a los equipos locales."}}, {"n": 6, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Devolver el balón al rival después de detener el juego por una lesión es un ejemplo de:", "opciones": {"A": "una regla obligatoria de la IFAB.", "B": "una estrategia para ganar tiempo.", "C": "juego limpio, aunque no sea una obligación del reglamento.", "D": "una falta que se sanciona con tarjeta."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué caso un jugador puede tocar el balón con la mano sin cometer falta?", "opciones": {"A": "En cualquier saque de esquina.", "B": "Cuando es el capitán.", "C": "Cuando es el guardameta dentro de su propia área.", "D": "Cuando el balón viene muy rápido."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En el sistema 1-4-4-2, ¿cuántos delanteros hay?", "opciones": {"A": "Dos.", "B": "Uno.", "C": "Tres.", "D": "Cuatro."}}, {"n": 9, "seccion": 2, "competencia": "Lexical", "enunciado": "Un «sistema táctico» es:", "opciones": {"A": "el uniforme de cada equipo.", "B": "el reglamento oficial del fútbol.", "C": "la forma en que un equipo distribuye a sus jugadores en el campo.", "D": "el entrenamiento físico del equipo."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué el 1-4-3-3 favorece el juego por las bandas?", "opciones": {"A": "Porque tiene cinco defensas.", "B": "Porque el portero juega adelantado.", "C": "Porque no tiene mediocampistas.", "D": "Porque tiene tres delanteros, que pueden abrirse hacia los costados."}}, {"n": 11, "seccion": 2, "competencia": "Literal", "enunciado": "La transición ataque-defensa ocurre cuando el equipo:", "opciones": {"A": "recupera el balón.", "B": "cobra un tiro libre.", "C": "hace un cambio de jugador.", "D": "pierde el balón."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu equipo acaba de recuperar el balón y el rival tiene a varios jugadores adelantados. ¿Qué es lo más conveniente según el texto?", "opciones": {"A": "Sacar el balón por la banda.", "B": "Pasar el balón hacia atrás y esperar.", "C": "Detener el juego para hacer un cambio.", "D": "Salir rápido hacia el arco rival antes de que se organice."}}, {"n": 13, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué los equipos que dominan las transiciones suelen anotar más?", "opciones": {"A": "Porque el árbitro los favorece.", "B": "Porque aprovechan los momentos en que el rival está desordenado.", "C": "Porque juegan más minutos.", "D": "Porque tienen más jugadores en el campo."}}, {"n": 14, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu equipo pierde el balón en campo rival. ¿Qué deben hacer los jugadores más cercanos?", "opciones": {"A": "Detenerse y reclamar al árbitro.", "B": "Esperar a que el rival se equivoque.", "C": "Correr todos hacia su propia área.", "D": "Presionar de inmediato para recuperarlo o retrasar al rival."}}, {"n": 15, "seccion": 3, "competencia": "Lexical", "enunciado": "En el tercer texto, «cambiar el ritmo» significa:", "opciones": {"A": "cambiar la música del estadio.", "B": "cambiar de sistema táctico en cada jugada.", "C": "jugar siempre a la máxima velocidad.", "D": "alternar acciones lentas y rápidas para sorprender al rival."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Cómo puede un delantero superar a un defensor más rápido que él?", "opciones": {"A": "Esperando a que el defensor se canse.", "B": "Conduciendo despacio y acelerando de repente.", "C": "Pasando siempre hacia atrás.", "D": "Corriendo siempre a la misma velocidad."}}, {"n": 17, "seccion": 3, "competencia": "Literal", "enunciado": "Según el texto, ¿qué ejemplos muestran el fútbol como expresión cultural?", "opciones": {"A": "Las medidas del campo y del balón.", "B": "Las celebraciones, los cantos de la hinchada y los estilos de juego regionales.", "C": "Las tarjetas amarillas y rojas.", "D": "Los sistemas 1-4-4-2 y 1-4-3-3."}}, {"n": 18, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué postura defiende el autor sobre la diversidad en el fútbol?", "opciones": {"A": "La diversidad enriquece la cultura del fútbol y la violencia la destruye.", "B": "Todas las hinchadas deberían animar igual.", "C": "Solo el estilo de toque es válido.", "D": "Las celebraciones deberían prohibirse."}}, {"n": 19, "seccion": 3, "competencia": "Aplicación", "enunciado": "En un partido escolar, un compañero se burla de la forma de celebrar del equipo rival. Según el texto, ¿qué actitud sería la adecuada?", "opciones": {"A": "Respetar la expresión del rival y animar a tu compañero a hacer lo mismo.", "B": "Burlarse también para defender al equipo.", "C": "Pedir al árbitro que expulse al rival.", "D": "Ignorar el partido y retirarse."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué idea integra los tres textos?", "opciones": {"A": "El fútbol depende solo de la técnica individual.", "B": "El reglamento es lo único importante.", "C": "Jugar bien al fútbol combina respetar las reglas, organizarse tácticamente y expresarse con respeto.", "D": "La táctica no tiene relación con el ritmo del juego."}}]}, {"id": "2027-g11-p1-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 1", "titulo": "Quiz — Actividad física y salud (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "¿Cuánta actividad física necesitamos?", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "La Organización Mundial de la Salud (OMS) recomienda que los niños y adolescentes de 5 a 17 años realicen, en promedio, al menos 60 minutos diarios de actividad física de intensidad moderada a vigorosa, principalmente aeróbica. Además, al menos tres días a la semana deberían incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. Para los adultos, la recomendación es de 150 a 300 minutos semanales de actividad moderada, o de 75 a 150 minutos de actividad vigorosa, más ejercicios de fuerza dos o más días por semana.<br><br>La intensidad moderada es aquella en la que la respiración y el pulso se aceleran, pero todavía se puede conversar; caminar a paso rápido o montar en bicicleta suave son ejemplos. En la intensidad vigorosa, como correr o jugar un partido, la respiración es tan agitada que cuesta hablar. La OMS también recomienda reducir el tiempo sedentario, por ejemplo el que se pasa frente a pantallas. La actividad física regular mejora la salud del corazón y los pulmones, fortalece huesos y músculos, ayuda a controlar el peso y favorece el bienestar mental y el rendimiento escolar."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánta actividad física diaria recomienda la OMS para adolescentes de 5 a 17 años?", "opciones": {"A": "Dos horas diarias de intensidad vigorosa.", "B": "Al menos 60 minutos en promedio, de intensidad moderada a vigorosa.", "C": "Una hora a la semana.", "D": "Al menos 20 minutos de intensidad suave."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos días a la semana deberían incluir actividades de fortalecimiento muscular y óseo los adolescentes?", "opciones": {"A": "Al menos tres.", "B": "Ninguno, solo actividad aeróbica.", "C": "Los siete días obligatoriamente.", "D": "Al menos uno."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "Según el texto, en una actividad de intensidad «moderada»:", "opciones": {"A": "es imposible hablar.", "B": "no se acelera el pulso.", "C": "solo se mueven los brazos.", "D": "la respiración se acelera, pero todavía se puede conversar."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cuál de estas actividades es vigorosa?", "opciones": {"A": "Correr o jugar un partido de fútbol.", "B": "Estar sentado leyendo.", "C": "Caminar despacio por el parque.", "D": "Estirarse suavemente."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es la recomendación semanal de actividad moderada para adultos?", "opciones": {"A": "No hay recomendación para adultos.", "B": "De 150 a 300 minutos.", "C": "De 30 a 60 minutos.", "D": "De 500 a 600 minutos."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la OMS recomienda reducir el tiempo frente a pantallas?", "opciones": {"A": "Porque es una regla del colegio.", "B": "Porque es tiempo sedentario que afecta la salud.", "C": "Porque así se estudia más.", "D": "Porque las pantallas impiden dormir siempre."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante camina 20 minutos al colegio y 20 de regreso, y juega 30 minutos en el descanso. ¿Cumple la recomendación diaria?", "opciones": {"A": "No, porque debe hacerlo de una sola vez.", "B": "Sí, pero solo si lo hace los fines de semana.", "C": "Sí, suma 70 minutos si la intensidad es al menos moderada.", "D": "No, porque caminar nunca cuenta."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál es un beneficio de la actividad física regular?", "opciones": {"A": "Elimina la necesidad de dormir.", "B": "Reemplaza una alimentación balanceada.", "C": "Solo mejora la apariencia física.", "D": "Favorece el bienestar mental y el rendimiento escolar."}}, {"n": 9, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «sedentario» se refiere a:", "opciones": {"A": "hacer ejercicio sentado.", "B": "vivir en una zona rural.", "C": "pasar mucho tiempo sentado o con muy poco movimiento.", "D": "entrenar de forma vigorosa."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la mejor conclusión del texto?", "opciones": {"A": "Moverse con regularidad y a la intensidad adecuada es una necesidad para la salud.", "B": "Basta con hacer ejercicio un día al mes.", "C": "Solo los deportistas necesitan actividad física.", "D": "La actividad física es útil únicamente para bajar de peso."}}], "modalidad": "Quiz"}, {"id": "2027-g11-p1", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Atletismo y plan personal de entrenamiento (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Los principios del entrenamiento", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Entrenar no es hacer ejercicio sin orden: es aplicar principios que permiten mejorar sin lesionarse. El principio de sobrecarga progresiva indica que el cuerpo solo mejora si recibe estímulos un poco mayores a los que está acostumbrado; por eso la carga (tiempo, distancia, velocidad o peso) se aumenta de forma gradual, no de golpe. El principio de especificidad dice que el cuerpo se adapta a lo que se entrena: quien quiere mejorar en una carrera de 5 kilómetros debe correr distancias largas, no solo levantar pesas.<br><br>El principio de individualidad recuerda que cada persona responde distinto al mismo entrenamiento, según su edad, su experiencia y su estado físico. El principio de recuperación señala que el cuerpo se fortalece durante el descanso: sin dormir bien, hidratarse y alimentarse, el entrenamiento produce fatiga en lugar de mejoras. Finalmente, el principio de continuidad advierte que los beneficios se pierden si se abandona la práctica durante semanas; es mejor entrenar tres veces por semana todo el año que siete veces durante un mes y luego dejarlo."}, {"id": 2, "titulo": "La sesión y la frecuencia cardiaca", "instruccion": "(Responda las preguntas 8 a 13 con base en el siguiente texto.)", "cuerpo": "Una sesión de entrenamiento tiene tres partes. El calentamiento (10 a 15 minutos) eleva poco a poco la temperatura del cuerpo y la frecuencia cardiaca, con trote suave, movilidad articular y ejercicios de técnica de carrera. La parte principal desarrolla el objetivo del día: por ejemplo, carrera continua, series de velocidad o saltos. La vuelta a la calma (5 a 10 minutos) baja la intensidad con trote suave, caminata y estiramientos.<br><br>La frecuencia cardiaca (FC) es el número de latidos del corazón por minuto y sirve para controlar la intensidad. Una fórmula sencilla para estimar la frecuencia cardiaca máxima es restar la edad a 220: un estudiante de 16 años tendría una FC máxima aproximada de 204 latidos por minuto. Para mejorar la resistencia aeróbica se recomienda trabajar entre el 60 % y el 80 % de esa frecuencia máxima. El pulso se puede tomar en la muñeca o en el cuello, contando los latidos durante 15 segundos y multiplicando por cuatro. Esta fórmula es una estimación: la percepción del esfuerzo y la orientación del docente también son importantes."}, {"id": 3, "titulo": "Del test al plan personal", "instruccion": "(Responda las preguntas 14 a 20 con base en el siguiente texto.)", "cuerpo": "Para diseñar un plan, primero hay que saber de dónde se parte. El test de Cooper consiste en correr la mayor distancia posible en 12 minutos y permite estimar la resistencia aeróbica. Con ese resultado, cada estudiante se plantea una meta. Una buena meta es específica, medible, alcanzable, relevante y con un tiempo definido: por ejemplo, «aumentar 200 metros mi resultado en el test de Cooper en ocho semanas», y no simplemente «estar en forma».<br><br>Un plan sencillo para un estudiante que empieza puede incluir tres sesiones por semana en días no consecutivos, con 20 a 30 minutos de carrera continua a intensidad moderada, y aumentar el tiempo de carrera de forma gradual cada semana. Es útil registrar cada sesión: fecha, duración, sensación de esfuerzo y frecuencia cardiaca. Al final del periodo, se repite el test para comparar. Integrar la actividad física al proyecto de vida significa que no depende de una nota ni de un uniforme: es una decisión personal que acompaña a la persona después del colegio."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Lexical", "enunciado": "El principio de «sobrecarga progresiva» indica que:", "opciones": {"A": "la carga del entrenamiento debe aumentar de forma gradual.", "B": "el descanso no es necesario.", "C": "todas las personas deben entrenar igual.", "D": "hay que entrenar siempre con el máximo peso posible."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una estudiante quiere mejorar su tiempo en una carrera de 5 km. Según el principio de especificidad, debería:", "opciones": {"A": "incluir carreras de distancias largas en su entrenamiento.", "B": "entrenar solo la flexibilidad.", "C": "practicar únicamente saltos.", "D": "hacer solo ejercicios de pesas."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuándo se fortalece el cuerpo?", "opciones": {"A": "Únicamente en competencias.", "B": "Cuando se entrena sin descanso.", "C": "Solo durante el entrenamiento más intenso.", "D": "Durante el descanso, con sueño, hidratación y alimentación adecuados."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué dos compañeros con el mismo plan pueden obtener resultados distintos?", "opciones": {"A": "Porque uno de ellos hizo trampa.", "B": "Porque el principio de especificidad no funciona.", "C": "Por el principio de individualidad: cada persona responde diferente.", "D": "Porque el plan estaba mal escrito."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Qué opción respeta mejor el principio de continuidad?", "opciones": {"A": "Entrenar siete veces por semana un mes y luego descansar seis meses.", "B": "Entrenar tres veces por semana durante todo el año.", "C": "Entrenar un día muy fuerte cada dos meses.", "D": "Entrenar solo antes de los exámenes de Educación Física."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Qué puede pasar si se entrena mucho sin recuperación adecuada?", "opciones": {"A": "Se elimina el riesgo de lesiones.", "B": "Se mejora el doble de rápido.", "C": "Se acumula fatiga en lugar de lograr mejoras.", "D": "No ocurre nada, el descanso es opcional."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la tesis del primer texto?", "opciones": {"A": "Solo los atletas profesionales deben entrenar con principios.", "B": "Entrenar bien requiere aplicar principios para mejorar sin lesionarse.", "C": "Cualquier ejercicio sin orden produce los mismos resultados.", "D": "El descanso es una pérdida de tiempo."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuáles son las tres partes de una sesión de entrenamiento?", "opciones": {"A": "Estiramiento, competencia y descanso.", "B": "Trote, velocidad y fuerza.", "C": "Inicio, evaluación y premiación.", "D": "Calentamiento, parte principal y vuelta a la calma."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es la FC máxima estimada de un estudiante de 16 años según la fórmula del texto?", "opciones": {"A": "204 latidos por minuto.", "B": "220 latidos por minuto.", "C": "236 latidos por minuto.", "D": "180 latidos por minuto."}}, {"n": 10, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante de 17 años quiere entrenar resistencia aeróbica entre el 60 % y el 80 % de su FC máxima. ¿Cuál es el rango aproximado?", "opciones": {"A": "Entre 100 y 120 latidos por minuto.", "B": "Entre 60 y 80 latidos por minuto.", "C": "Entre 122 y 162 latidos por minuto.", "D": "Entre 170 y 203 latidos por minuto."}}, {"n": 11, "seccion": 2, "competencia": "Aplicación", "enunciado": "Contaste 35 latidos en 15 segundos. ¿Cuál es tu frecuencia cardiaca?", "opciones": {"A": "105 latidos por minuto.", "B": "35 latidos por minuto.", "C": "70 latidos por minuto.", "D": "140 latidos por minuto."}}, {"n": 12, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la vuelta a la calma?", "opciones": {"A": "Para medir el resultado del test de Cooper.", "B": "Para bajar la intensidad gradualmente después de la parte principal.", "C": "Para reemplazar el calentamiento.", "D": "Para aumentar al máximo la frecuencia cardiaca."}}, {"n": 13, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el texto aclara que la fórmula 220 menos la edad es «una estimación»?", "opciones": {"A": "Porque la fórmula está prohibida en los colegios.", "B": "Porque la frecuencia cardiaca no tiene relación con la intensidad.", "C": "Porque cada persona es diferente y también hay que considerar la percepción del esfuerzo.", "D": "Porque solo sirve para adultos mayores."}}, {"n": 14, "seccion": 3, "competencia": "Literal", "enunciado": "¿En qué consiste el test de Cooper?", "opciones": {"A": "En correr 100 metros lo más rápido posible.", "B": "En caminar durante una hora.", "C": "En saltar la mayor distancia desde parado.", "D": "En correr la mayor distancia posible en 12 minutos."}}, {"n": 15, "seccion": 3, "competencia": "Aplicación", "enunciado": "¿Cuál de estas metas cumple las características descritas en el texto?", "opciones": {"A": "Correr mucho más.", "B": "Ser el mejor del salón.", "C": "Estar en forma este año.", "D": "Aumentar 200 metros mi resultado del test de Cooper en ocho semanas."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el plan propone sesiones en días no consecutivos?", "opciones": {"A": "Porque el test de Cooper se hace cada dos días.", "B": "Para permitir la recuperación entre sesiones.", "C": "Porque está prohibido correr dos días seguidos.", "D": "Para que el plan dure menos semanas."}}, {"n": 17, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué datos se recomienda registrar en cada sesión?", "opciones": {"A": "Fecha, duración, sensación de esfuerzo y frecuencia cardiaca.", "B": "Únicamente la nota obtenida.", "C": "Solo el nombre del compañero de entrenamiento.", "D": "El clima y la ropa usada."}}, {"n": 18, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Para qué se repite el test al final del periodo?", "opciones": {"A": "Para calcular la FC máxima.", "B": "Para comparar el resultado con el inicial y valorar el progreso.", "C": "Para cambiar de deporte.", "D": "Para reemplazar el registro de sesiones."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, integrar la actividad física al proyecto de vida significa que:", "opciones": {"A": "termina al graduarse.", "B": "solo se practica con uniforme.", "C": "es una decisión personal que continúa después del colegio.", "D": "depende de la nota de Educación Física."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué relación hay entre los tres textos?", "opciones": {"A": "Los principios, el control de la intensidad y las metas permiten construir un plan personal de entrenamiento.", "B": "Los tres afirman que el descanso no es necesario.", "C": "Los tres explican la historia del atletismo.", "D": "Los tres tratan solo sobre la frecuencia cardiaca."}}]}, {"id": "2027-g10-p2-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 2", "titulo": "Quiz — Mitos y realidades de la vida saludable (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Lo que se dice en el colegio", "instruccion": "(Responda las preguntas 1 a 6 con base en el siguiente texto y en los recursos de Hábitos de vida saludables.)", "cuerpo": "En una encuesta rápida entre estudiantes de la media aparecieron varias frases que circulan en los descansos, en las redes sociales y hasta en el gimnasio. Algunas tienen respaldo científico y otras son mitos: creencias muy repetidas que no coinciden con lo que dicen los organismos de salud.<br><br>Para separar unas de otras sirve consultar fuentes confiables, como la Organización Mundial de la Salud (OMS) o la Academia Americana de Pediatría (AAP), que revisan la evidencia antes de dar una recomendación. En este quiz encontrarás seis de esas frases. Para cada una, elige la opción que la describe correctamente: si es un mito o una realidad, y por qué."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Aplicación", "enunciado": "«Las bebidas energizantes mejoran el rendimiento deportivo». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: la cafeína que contienen es necesaria para cualquier entrenamiento.", "B": "Realidad: reemplazan el agua y reponen todo lo que se pierde al sudar.", "C": "Mito: aportan cafeína y azúcares, no se recomiendan en adolescentes y, para la mayoría de las sesiones, basta con agua.", "D": "Mito: solo funcionan si se toman frías y antes del calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Hacer abdominales elimina la grasa del abdomen». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: no se pierde grasa localizada ejercitando una sola zona; las abdominales fortalecen el músculo.", "B": "Realidad: cada abdominal quema la grasa que está justo encima del músculo trabajado.", "C": "Realidad: basta con hacer cien abdominales diarias para reducir la cintura.", "D": "Mito: las abdominales no tienen ningún efecto sobre el cuerpo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "«Un adolescente debería acumular en promedio 60 minutos diarios de actividad física moderada a vigorosa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: la OMS recomienda solo 60 minutos a la semana.", "B": "Mito: esa recomendación es únicamente para deportistas de competencia.", "C": "Realidad, pero solo si los 60 minutos se hacen en una sola sesión sin pausas.", "D": "Realidad: es la recomendación de la OMS (2020) para niños y adolescentes de 5 a 17 años."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "«Sudar más significa que quemaste más grasa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el sudor es grasa que sale del cuerpo en forma líquida.", "B": "Mito: el sudor sirve para regular la temperatura del cuerpo; sudar más no indica que se haya quemado más grasa.", "C": "Realidad: por eso conviene entrenar con ropa plástica o muy abrigada.", "D": "Mito: sudar es una señal de que el ejercicio fue inútil."}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Dormir poco no afecta el rendimiento físico ni el académico». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el cuerpo se adapta a dormir cuatro o cinco horas sin consecuencias.", "B": "Realidad: el sueño solo es importante en la infancia.", "C": "Mito: dormir poco afecta la concentración, la memoria y el rendimiento; los adolescentes necesitan de 8 a 10 horas.", "D": "Mito: dormir poco solo afecta a quienes practican deporte."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "«La hidratación solo importa en los deportes de competencia». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: en una clase de Educación Física no se pierde agua.", "B": "Realidad: solo hay que beber cuando aparece una sed muy intensa.", "C": "Mito: hidratarse solo es necesario en días de mucho calor.", "D": "Mito: hay que hidratarse antes, durante y después de cualquier actividad física, incluida la clase y el juego."}}]}, {"id": "2027-g10-p3-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 3", "titulo": "Quiz — Chequeo saludable: actividad física, nutrición, hidratación y descanso (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 12, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Cuatro hábitos que sostienen la salud", "instruccion": "(Responda las preguntas 1 a 8 con base en el siguiente texto.)", "cuerpo": "<b>Actividad física.</b> Según las directrices de la Organización Mundial de la Salud (OMS, 2020), los niños y adolescentes de 5 a 17 años deberían acumular en promedio 60 minutos diarios de actividad física de intensidad moderada a vigorosa, en su mayoría aeróbica. Al menos tres días por semana conviene incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. También recomienda limitar el tiempo sedentario, en especial el que se pasa frente a pantallas por diversión.<br><br><b>Nutrición.</b> La OMS señala que una alimentación saludable incluye frutas, verduras, legumbres y cereales integrales. A partir de los 10 años se recomienda consumir al menos 400 gramos de frutas y verduras al día. Los azúcares libres —los que se añaden a bebidas y alimentos, y los de jugos y mieles— deberían ser menos del 10 % de la energía diaria, e idealmente menos del 5 %. También aconseja reducir la sal.<br><br><b>Hidratación.</b> La Academia Americana de Pediatría (AAP) explica que el agua es la mejor bebida para la mayoría de las actividades físicas de niños y adolescentes. Las bebidas deportivas, que aportan azúcares y electrolitos, solo pueden ayudar en actividades vigorosas y prolongadas. Las bebidas energizantes son otro producto: contienen cafeína y otros estimulantes, y los niños y adolescentes no deberían consumirlas.<br><br><b>Descanso.</b> La AAP apoya las pautas de la Academia Estadounidense de Medicina del Sueño: los adolescentes de 13 a 18 años necesitan de 8 a 10 horas de sueño en cada periodo de 24 horas. Dormir lo suficiente se relaciona con mejor memoria, comportamiento, rendimiento académico y salud mental; dormir poco se asocia con dificultades para concentrarse, dolores de cabeza y otros problemas de salud."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuánta actividad física recomienda la OMS a los adolescentes?", "opciones": {"A": "60 minutos a la semana, solo en la clase de Educación Física.", "B": "En promedio 60 minutos diarios de intensidad moderada a vigorosa.", "C": "Dos horas diarias de ejercicio de fuerza.", "D": "30 minutos de caminata suave, tres veces por semana."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Camila juega videojuegos cuatro horas al día y solo se mueve en la clase de Educación Física. Según la OMS, ¿qué le convendría cambiar primero?", "opciones": {"A": "Reducir el tiempo frente a la pantalla y sumar actividad física moderada a vigorosa casi todos los días.", "B": "Nada, porque la clase de Educación Física ya cubre lo recomendado.", "C": "Hacer ejercicio solo el fin de semana durante varias horas seguidas.", "D": "Cambiar los videojuegos por series de televisión."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué cantidad mínima de frutas y verduras al día recomienda la OMS a partir de los 10 años?", "opciones": {"A": "100 gramos.", "B": "200 gramos.", "C": "400 gramos.", "D": "Una sola fruta a la semana."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la expresión «azúcares libres» se refiere a:", "opciones": {"A": "el azúcar que contienen las frutas enteras y las verduras.", "B": "los alimentos que no tienen ningún tipo de azúcar.", "C": "los carbohidratos de los cereales integrales.", "D": "los azúcares que se añaden a bebidas y alimentos, y los de jugos y mieles."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según la AAP, ¿cuál es la mejor bebida para la mayoría de las actividades físicas de los adolescentes?", "opciones": {"A": "Una bebida energizante.", "B": "El agua.", "C": "Una gaseosa.", "D": "Una bebida deportiva en cualquier sesión."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto distingue entre bebidas deportivas y bebidas energizantes?", "opciones": {"A": "Porque las energizantes contienen cafeína y estimulantes que los adolescentes no deberían consumir.", "B": "Porque las energizantes hidratan mejor que el agua.", "C": "Porque las deportivas están prohibidas para menores de edad.", "D": "Porque ambas son iguales y solo cambia el sabor."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas horas de sueño necesitan los adolescentes de 13 a 18 años?", "opciones": {"A": "De 5 a 6 horas.", "B": "De 6 a 7 horas.", "C": "De 11 a 14 horas.", "D": "De 8 a 10 horas."}}, {"n": 8, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Andrés se acuesta a la 1:00 a. m. para terminar tareas y se levanta a las 5:30 a. m. ¿Qué conclusión es coherente con el texto?", "opciones": {"A": "Su horario es adecuado porque aprovecha mejor el tiempo.", "B": "Dormir poco solo le afectará si practica deporte.", "C": "Duerme menos de lo recomendado, lo que puede afectar su concentración, su memoria y su rendimiento.", "D": "Puede recuperar todo el sueño perdido durmiendo una siesta corta."}}]}, {"id": "2027-g11-p2-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 2", "titulo": "Quiz — Mitos y realidades de la vida saludable (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Lo que se dice en el colegio", "instruccion": "(Responda las preguntas 1 a 6 con base en el siguiente texto y en los recursos de Hábitos de vida saludables.)", "cuerpo": "En una encuesta rápida entre estudiantes de la media aparecieron varias frases que circulan en los descansos, en las redes sociales y hasta en el gimnasio. Algunas tienen respaldo científico y otras son mitos: creencias muy repetidas que no coinciden con lo que dicen los organismos de salud.<br><br>Para separar unas de otras sirve consultar fuentes confiables, como la Organización Mundial de la Salud (OMS) o la Academia Americana de Pediatría (AAP), que revisan la evidencia antes de dar una recomendación. En este quiz encontrarás seis de esas frases. Para cada una, elige la opción que la describe correctamente: si es un mito o una realidad, y por qué."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Aplicación", "enunciado": "«Las bebidas energizantes mejoran el rendimiento deportivo». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: la cafeína que contienen es necesaria para cualquier entrenamiento.", "B": "Realidad: reemplazan el agua y reponen todo lo que se pierde al sudar.", "C": "Mito: aportan cafeína y azúcares, no se recomiendan en adolescentes y, para la mayoría de las sesiones, basta con agua.", "D": "Mito: solo funcionan si se toman frías y antes del calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Hacer abdominales elimina la grasa del abdomen». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: no se pierde grasa localizada ejercitando una sola zona; las abdominales fortalecen el músculo.", "B": "Realidad: cada abdominal quema la grasa que está justo encima del músculo trabajado.", "C": "Realidad: basta con hacer cien abdominales diarias para reducir la cintura.", "D": "Mito: las abdominales no tienen ningún efecto sobre el cuerpo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "«Un adolescente debería acumular en promedio 60 minutos diarios de actividad física moderada a vigorosa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: la OMS recomienda solo 60 minutos a la semana.", "B": "Mito: esa recomendación es únicamente para deportistas de competencia.", "C": "Realidad, pero solo si los 60 minutos se hacen en una sola sesión sin pausas.", "D": "Realidad: es la recomendación de la OMS (2020) para niños y adolescentes de 5 a 17 años."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "«Sudar más significa que quemaste más grasa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el sudor es grasa que sale del cuerpo en forma líquida.", "B": "Mito: el sudor sirve para regular la temperatura del cuerpo; sudar más no indica que se haya quemado más grasa.", "C": "Realidad: por eso conviene entrenar con ropa plástica o muy abrigada.", "D": "Mito: sudar es una señal de que el ejercicio fue inútil."}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Dormir poco no afecta el rendimiento físico ni el académico». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el cuerpo se adapta a dormir cuatro o cinco horas sin consecuencias.", "B": "Realidad: el sueño solo es importante en la infancia.", "C": "Mito: dormir poco afecta la concentración, la memoria y el rendimiento; los adolescentes necesitan de 8 a 10 horas.", "D": "Mito: dormir poco solo afecta a quienes practican deporte."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "«La hidratación solo importa en los deportes de competencia». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: en una clase de Educación Física no se pierde agua.", "B": "Realidad: solo hay que beber cuando aparece una sed muy intensa.", "C": "Mito: hidratarse solo es necesario en días de mucho calor.", "D": "Mito: hay que hidratarse antes, durante y después de cualquier actividad física, incluida la clase y el juego."}}]}, {"id": "2027-g11-p3-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 3", "titulo": "Quiz — Chequeo saludable: actividad física, nutrición, hidratación y descanso (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 12, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Cuatro hábitos que sostienen la salud", "instruccion": "(Responda las preguntas 1 a 8 con base en el siguiente texto.)", "cuerpo": "<b>Actividad física.</b> Según las directrices de la Organización Mundial de la Salud (OMS, 2020), los niños y adolescentes de 5 a 17 años deberían acumular en promedio 60 minutos diarios de actividad física de intensidad moderada a vigorosa, en su mayoría aeróbica. Al menos tres días por semana conviene incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. También recomienda limitar el tiempo sedentario, en especial el que se pasa frente a pantallas por diversión.<br><br><b>Nutrición.</b> La OMS señala que una alimentación saludable incluye frutas, verduras, legumbres y cereales integrales. A partir de los 10 años se recomienda consumir al menos 400 gramos de frutas y verduras al día. Los azúcares libres —los que se añaden a bebidas y alimentos, y los de jugos y mieles— deberían ser menos del 10 % de la energía diaria, e idealmente menos del 5 %. También aconseja reducir la sal.<br><br><b>Hidratación.</b> La Academia Americana de Pediatría (AAP) explica que el agua es la mejor bebida para la mayoría de las actividades físicas de niños y adolescentes. Las bebidas deportivas, que aportan azúcares y electrolitos, solo pueden ayudar en actividades vigorosas y prolongadas. Las bebidas energizantes son otro producto: contienen cafeína y otros estimulantes, y los niños y adolescentes no deberían consumirlas.<br><br><b>Descanso.</b> La AAP apoya las pautas de la Academia Estadounidense de Medicina del Sueño: los adolescentes de 13 a 18 años necesitan de 8 a 10 horas de sueño en cada periodo de 24 horas. Dormir lo suficiente se relaciona con mejor memoria, comportamiento, rendimiento académico y salud mental; dormir poco se asocia con dificultades para concentrarse, dolores de cabeza y otros problemas de salud."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuánta actividad física recomienda la OMS a los adolescentes?", "opciones": {"A": "60 minutos a la semana, solo en la clase de Educación Física.", "B": "En promedio 60 minutos diarios de intensidad moderada a vigorosa.", "C": "Dos horas diarias de ejercicio de fuerza.", "D": "30 minutos de caminata suave, tres veces por semana."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Camila juega videojuegos cuatro horas al día y solo se mueve en la clase de Educación Física. Según la OMS, ¿qué le convendría cambiar primero?", "opciones": {"A": "Reducir el tiempo frente a la pantalla y sumar actividad física moderada a vigorosa casi todos los días.", "B": "Nada, porque la clase de Educación Física ya cubre lo recomendado.", "C": "Hacer ejercicio solo el fin de semana durante varias horas seguidas.", "D": "Cambiar los videojuegos por series de televisión."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué cantidad mínima de frutas y verduras al día recomienda la OMS a partir de los 10 años?", "opciones": {"A": "100 gramos.", "B": "200 gramos.", "C": "400 gramos.", "D": "Una sola fruta a la semana."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la expresión «azúcares libres» se refiere a:", "opciones": {"A": "el azúcar que contienen las frutas enteras y las verduras.", "B": "los alimentos que no tienen ningún tipo de azúcar.", "C": "los carbohidratos de los cereales integrales.", "D": "los azúcares que se añaden a bebidas y alimentos, y los de jugos y mieles."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según la AAP, ¿cuál es la mejor bebida para la mayoría de las actividades físicas de los adolescentes?", "opciones": {"A": "Una bebida energizante.", "B": "El agua.", "C": "Una gaseosa.", "D": "Una bebida deportiva en cualquier sesión."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto distingue entre bebidas deportivas y bebidas energizantes?", "opciones": {"A": "Porque las energizantes contienen cafeína y estimulantes que los adolescentes no deberían consumir.", "B": "Porque las energizantes hidratan mejor que el agua.", "C": "Porque las deportivas están prohibidas para menores de edad.", "D": "Porque ambas son iguales y solo cambia el sabor."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas horas de sueño necesitan los adolescentes de 13 a 18 años?", "opciones": {"A": "De 5 a 6 horas.", "B": "De 6 a 7 horas.", "C": "De 11 a 14 horas.", "D": "De 8 a 10 horas."}}, {"n": 8, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Andrés se acuesta a la 1:00 a. m. para terminar tareas y se levanta a las 5:30 a. m. ¿Qué conclusión es coherente con el texto?", "opciones": {"A": "Su horario es adecuado porque aprovecha mejor el tiempo.", "B": "Dormir poco solo le afectará si practica deporte.", "C": "Duerme menos de lo recomendado, lo que puede afectar su concentración, su memoria y su rendimiento.", "D": "Puede recuperar todo el sueño perdido durmiendo una siesta corta."}}]}, {"id": "2027-g6-p2-quiz1", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Habilidades motrices: moverse con control (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Habilidades motrices: moverse con control", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las habilidades motrices básicas son los movimientos que el cuerpo aprende para desenvolverse en el juego y en el deporte. Se agrupan en tres tipos. Las habilidades locomotrices llevan el cuerpo de un lugar a otro: caminar, correr, saltar, galopar y deslizarse. Las habilidades manipulativas trabajan con objetos: lanzar, atrapar, golpear, patear y conducir un balón. Las habilidades de equilibrio o estabilidad permiten mantener el cuerpo controlado, ya sea quieto (equilibrio estático) o en movimiento (equilibrio dinámico), como al girar o al caminar sobre una línea.<br><br>Estas habilidades no se aprenden de un día para otro: mejoran con la práctica repetida, primero en situaciones sencillas y luego en juegos con más compañeros y reglas. Por eso en las clases se usan los juegos predeportivos, que son juegos con reglas simples que preparan al estudiante para un deporte sin exigirle todavía la técnica completa."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, las habilidades locomotrices sirven para:", "opciones": {"A": "trabajar únicamente con objetos.", "B": "llevar el cuerpo de un lugar a otro.", "C": "mantener el cuerpo siempre quieto.", "D": "cambiar las reglas del juego."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál de las siguientes es una habilidad manipulativa?", "opciones": {"A": "Lanzar y atrapar un balón.", "B": "Galopar.", "C": "Mantenerse en un solo pie.", "D": "Deslizarse hacia un lado."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "El equilibrio dinámico ocurre cuando el cuerpo:", "opciones": {"A": "permanece completamente quieto.", "B": "se mantiene controlado mientras se mueve.", "C": "pierde el control al girar.", "D": "se apoya siempre en un compañero."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «predeportivos» se refiere a juegos que:", "opciones": {"A": "preparan para un deporte con reglas simples.", "B": "reemplazan a los deportes oficiales.", "C": "solo se juegan en competencias.", "D": "exigen la técnica completa desde el inicio."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se practica primero en situaciones sencillas y luego en juegos con más compañeros?", "opciones": {"A": "Porque los compañeros estorban al principio.", "B": "Porque el aprendizaje avanza de lo fácil a lo complejo.", "C": "Porque las reglas solo se usan al final.", "D": "Porque las habilidades se aprenden de un día para otro."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante pierde el control cuando gira sobre una línea de equilibrio. ¿Qué habilidad debe reforzar?", "opciones": {"A": "El equilibrio dinámico.", "B": "El lanzamiento de precisión.", "C": "El galope.", "D": "La conducción de balón con el pie."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para practicar una habilidad manipulativa en parejas, la actividad más adecuada es:", "opciones": {"A": "correr dos vueltas sin parar.", "B": "quedarse quieto con los ojos cerrados.", "C": "pasarse un balón con ambas manos a distintas distancias.", "D": "saltar la cuerda sin ningún objeto."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Según el texto, las habilidades mejoran con la práctica repetida. Si un estudiante practica una sola vez, lo más probable es que:", "opciones": {"A": "la domine por completo.", "B": "pase a jugar un deporte oficial.", "C": "ya no necesite las reglas.", "D": "no consolide la habilidad."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "El texto clasifica las habilidades motrices básicas en:", "opciones": {"A": "rápidas y lentas.", "B": "de fuerza, resistencia y velocidad.", "C": "locomotrices, manipulativas y de equilibrio.", "D": "una distinta por cada deporte."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "El equilibrio es la única habilidad importante.", "B": "Los juegos con reglas simples no sirven para aprender.", "C": "Las habilidades motrices se tienen desde el nacimiento y no se entrenan.", "D": "Las habilidades motrices se aprenden con la práctica y se agrupan en tres tipos que se aplican en el juego."}}]}, {"id": "2027-g6-p2-quiz2", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Minifútbol y minibaloncesto: reglas básicas (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Minifútbol y minibaloncesto: reglas básicas", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En la clase de Educación Física se practican versiones reducidas de los deportes para que todos jueguen más. El minifútbol se juega entre equipos pequeños, por lo general de cuatro o cinco jugadores, en una cancha más corta que la de fútbol. El balón se juega con los pies y no se puede tocar con las manos, salvo el portero dentro de su área. Se anota un gol cuando el balón cruza completamente la línea de la portería. Son faltas empujar, hacer zancadilla, agarrar al rival y jugar el balón con la mano; la sanción es un tiro libre para el equipo contrario. Cuando el balón sale por una línea lateral, se reanuda con un saque de banda.<br><br>El minibaloncesto 3 contra 3 se juega en media cancha, con un solo aro. Se avanza con el balón botándolo con una mano; si el jugador lo agarra con las dos manos y vuelve a botarlo, comete doble drible, y si camina con el balón sin botarlo, comete pasos. Cada canasta vale un punto, o dos si se lanza desde detrás del arco. Las faltas personales —empujar, golpear o agarrar— se sancionan con la posesión para el equipo contrario. En ambos deportes, el juego limpio significa respetar las reglas, a los compañeros y al árbitro, aunque este sea un estudiante."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuántos jugadores tiene por lo general un equipo de minifútbol?", "opciones": {"A": "Cuatro o cinco.", "B": "Siete u ocho.", "C": "Dos o tres.", "D": "Once."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuándo se anota un gol?", "opciones": {"A": "Cuando el balón toca el poste.", "B": "Cuando el balón cruza completamente la línea de la portería.", "C": "Cuando el portero suelta el balón.", "D": "Cuando el balón toca la línea lateral."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se reanuda el juego cuando el balón sale por una línea lateral?", "opciones": {"A": "Con un saque de banda.", "B": "Con un tiro libre directo.", "C": "Con un penal.", "D": "Con un salto entre dos."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «doble drible» significa:", "opciones": {"A": "agarrar el balón con las dos manos y volver a botarlo.", "B": "botar el balón con una sola mano.", "C": "lanzar dos veces seguidas al aro.", "D": "pasar el balón a dos compañeros."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué en la clase se practican versiones reducidas de los deportes?", "opciones": {"A": "Para que los deportes sean más difíciles.", "B": "Para eliminar al árbitro.", "C": "Para que solo jueguen los mejores.", "D": "Para que todos jueguen más y participen."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un 3 contra 3, una jugadora agarra el balón con las dos manos y vuelve a botarlo. ¿Qué falta comete?", "opciones": {"A": "Pasos.", "B": "Falta personal.", "C": "Ninguna.", "D": "Doble drible."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "En minifútbol, un jugador que no es portero toca el balón con la mano. ¿Qué se sanciona?", "opciones": {"A": "Un gol para su equipo.", "B": "Un saque de banda para él.", "C": "Un tiro libre para el equipo contrario.", "D": "Nada."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto vale una canasta lanzada desde detrás del arco, según el texto?", "opciones": {"A": "Un punto.", "B": "Dos puntos.", "C": "Tres puntos.", "D": "Cinco puntos."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué una falta personal se sanciona con la posesión para el equipo contrario?", "opciones": {"A": "Porque así se premia al que empuja.", "B": "Porque el juego se hace más lento.", "C": "Porque el reglamento protege la seguridad y evita ventajas por juego brusco.", "D": "Porque en la clase no hay árbitro."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿qué significa jugar limpio?", "opciones": {"A": "Ganar a cualquier costo.", "B": "Respetar las reglas, a los compañeros y al árbitro.", "C": "Discutir todas las decisiones.", "D": "Evitar a los compañeros menos hábiles."}}]}, {"id": "2027-g6-p2-taller", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Capacidades físicomotrices y test (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Velocidad, agilidad y fuerza: tres capacidades en juego", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Las capacidades físicomotrices son las que permiten que el cuerpo se mueva con eficacia. La velocidad es la capacidad de reaccionar y desplazarse en el menor tiempo posible; se nota al salir corriendo ante una señal o al llegar primero a un balón. La agilidad es la facilidad para cambiar de dirección o de posición sin perder el control, como al esquivar en un juego de persecución. La fuerza es la capacidad de vencer una resistencia; en las piernas se manifiesta como potencia al saltar.<br><br>Estas capacidades se desarrollan jugando: los juegos de persecución, los relevos y los saltos mejoran a la vez la velocidad, la agilidad y la fuerza. Cada estudiante avanza a su propio ritmo; lo importante no es ser el más rápido, sino mejorar frente a sí mismo. Por eso, antes de cada trabajo se hace un calentamiento y, al final, una vuelta a la calma para recuperar el cuerpo."}, {"id": 2, "titulo": "Cómo se hace el test de velocidad y salto", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "En la clase se miden dos capacidades con pruebas sencillas. La primera es la velocidad, con una carrera de 30 metros. El estudiante se ubica detrás de la línea de salida, con un pie adelante; al escuchar la señal corre lo más rápido que puede hasta cruzar la línea de meta, y un compañero registra el tiempo con un cronómetro.<br><br>La segunda es el salto largo sin impulso, que mide la potencia de las piernas: el estudiante se pone detrás de una línea con los pies separados, flexiona las rodillas, balancea los brazos y salta hacia adelante con los dos pies a la vez. Se mide la distancia desde la línea hasta el punto de contacto más cercano al cuerpo; se hacen dos intentos y se anota el mejor. Para que los resultados sirvan, cada prueba se hace con calentamiento previo, en el mismo lugar y con las mismas indicaciones. Los datos se anotan en una ficha personal."}, {"id": 3, "titulo": "Interpretar mis resultados", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Después de aplicar el test, el trabajo continúa en el aula. Con la ficha personal, cada estudiante construye una tabla con sus datos: el tiempo de los 30 metros y la distancia del salto. Luego puede compararlos con las mediciones siguientes y ver si mejoraron. Interpretar un resultado significa preguntarse qué dice sobre el propio cuerpo: un tiempo menor en la carrera indica mayor velocidad, y una distancia mayor en el salto indica más potencia en las piernas.<br><br>También es importante preguntarse por qué: dormir poco, no calentar o no practicar pueden afectar el resultado. A partir de las conclusiones, cada estudiante propone una meta realista —por ejemplo, mejorar el salto en cinco centímetros— y las actividades que hará para alcanzarla. Comparar los resultados con los de otros compañeros no sirve para juzgar, porque cada cuerpo parte de condiciones diferentes."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿qué es la agilidad?", "opciones": {"A": "La capacidad de vencer una resistencia.", "B": "La capacidad de moverse en el menor tiempo posible.", "C": "La facilidad para cambiar de dirección o de posición sin perder el control.", "D": "La capacidad de mantener un esfuerzo largo."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se manifiesta la fuerza en las piernas?", "opciones": {"A": "Como velocidad de reacción.", "B": "Como flexibilidad.", "C": "Como equilibrio estático.", "D": "Como potencia al saltar."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En la frase «vencer una resistencia», la palabra «resistencia» se refiere a:", "opciones": {"A": "el cansancio al final de una carrera.", "B": "el tiempo que dura un juego.", "C": "el calentamiento previo.", "D": "la fuerza o carga que se opone a un movimiento."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué los juegos de persecución mejoran varias capacidades a la vez?", "opciones": {"A": "Porque exigen reaccionar, cambiar de dirección e impulsarse con las piernas.", "B": "Porque se juegan sin moverse.", "C": "Porque no tienen reglas.", "D": "Porque solo trabajan la flexibilidad."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para mejorar la agilidad, la actividad más adecuada es:", "opciones": {"A": "caminar en línea recta.", "B": "un recorrido de conos con cambios de dirección.", "C": "permanecer sentado.", "D": "levantar un objeto pesado una sola vez."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero llegó de último en una carrera, pero ahora corre más rápido que hace un mes. Según el texto, su resultado:", "opciones": {"A": "es un avance, porque lo importante es mejorar frente a sí mismo.", "B": "no tiene ningún valor.", "C": "indica que debe dejar la actividad.", "D": "es peor que el de los demás."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué se hace una vuelta a la calma al final del trabajo?", "opciones": {"A": "Para empezar otra carrera.", "B": "Para recuperar el cuerpo después del esfuerzo.", "C": "Para eliminar el calentamiento.", "D": "Para medir la velocidad."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuántos metros mide la carrera de velocidad del test?", "opciones": {"A": "30 metros.", "B": "50 metros.", "C": "100 metros.", "D": "400 metros."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuántos intentos se hacen en el salto largo sin impulso y cuál se anota?", "opciones": {"A": "Un intento, y se anota ese.", "B": "Dos intentos, y se anota el mejor.", "C": "Tres intentos, y se promedian.", "D": "Cinco intentos, y se anota el último."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, la palabra «potencia» se refiere a:", "opciones": {"A": "el descanso entre intentos.", "B": "el cansancio de las piernas.", "C": "el equilibrio al caer.", "D": "la fuerza aplicada con rapidez."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué cada prueba se hace en el mismo lugar y con las mismas indicaciones?", "opciones": {"A": "Para que los resultados se puedan comparar entre una medición y otra.", "B": "Para que la prueba dure más.", "C": "Para que todos saquen la misma nota.", "D": "Para evitar el calentamiento."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "En la carrera de 30 metros, ¿qué debe hacer el estudiante al escuchar la señal?", "opciones": {"A": "Esperar a que corran los demás.", "B": "Correr lo más rápido posible hasta cruzar la meta.", "C": "Caminar hasta la meta.", "D": "Saltar sin correr."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "En el salto largo sin impulso, un estudiante cae con un solo pie. ¿Qué debe corregir?", "opciones": {"A": "Caer siempre con un solo pie.", "B": "Saltar de espaldas.", "C": "Tomar impulso con una carrera.", "D": "Saltar y caer con los dos pies a la vez."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué utilidad tiene anotar los datos en una ficha personal?", "opciones": {"A": "Sirve para presumir ante los compañeros.", "B": "Reemplaza la prueba.", "C": "Permite comparar el progreso propio con mediciones posteriores.", "D": "No tiene ninguna utilidad."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué se construye con los datos de la ficha personal?", "opciones": {"A": "Una tabla con el tiempo de la carrera y la distancia del salto.", "B": "Un reglamento.", "C": "Un partido.", "D": "Un mapa del colegio."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, «interpretar» un resultado significa:", "opciones": {"A": "ocultarlo.", "B": "repetir la prueba.", "C": "explicar qué dice sobre el propio cuerpo.", "D": "compararlo con el de otro."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué comparar los resultados con los de otros compañeros no sirve para juzgar?", "opciones": {"A": "Porque todos los cuerpos son iguales.", "B": "Porque está prohibido anotar datos.", "C": "Porque no existen datos.", "D": "Porque cada cuerpo parte de condiciones diferentes."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un estudiante mejoró de 8,0 a 7,5 segundos en los 30 metros. ¿Qué indica ese cambio?", "opciones": {"A": "Que disminuyó su velocidad.", "B": "Que empeoró su salto.", "C": "Que aumentó su velocidad.", "D": "Que no cambió su condición."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál de estas es una meta realista?", "opciones": {"A": "Saltar el doble en una semana.", "B": "Mejorar el salto en cinco centímetros con práctica regular.", "C": "Superar al mejor del curso en un día.", "D": "Dejar de practicar para no cansarse."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Relacionando las tres lecturas, un buen proceso con el test físico incluye:", "opciones": {"A": "medir una vez y olvidar los datos.", "B": "comparar para decidir quién es mejor.", "C": "medir con cuidado, interpretar los resultados y proponer metas propias para mejorar.", "D": "evitar el calentamiento para ahorrar tiempo."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g7-p2-quiz1", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Las capacidades físicas básicas (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Las capacidades físicas básicas", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las capacidades físicas básicas son cuatro: fuerza, resistencia, velocidad y flexibilidad. La fuerza es la capacidad de vencer una resistencia o una carga, por ejemplo, al saltar, empujar o cargar un peso. La resistencia permite mantener un esfuerzo durante un tiempo prolongado sin cansarse demasiado, como al trotar quince minutos. La velocidad es la capacidad de realizar un movimiento o recorrer una distancia en el menor tiempo posible. La flexibilidad es la amplitud con la que se pueden mover las articulaciones y estirar los músculos.<br><br>Estas capacidades no se desarrollan igual en todas las personas ni al mismo ritmo: dependen de la edad, de los hábitos y de la práctica regular. Un buen calentamiento prepara el cuerpo para trabajarlas sin lesiones, y la vuelta a la calma ayuda a recuperarse. Por eso, antes de pensar en jugar un partido, conviene conocer qué capacidades se necesitan y cómo se entrenan."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas capacidades físicas básicas menciona el texto?", "opciones": {"A": "Cuatro.", "B": "Dos.", "C": "Seis.", "D": "Tres."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "La resistencia permite:", "opciones": {"A": "recorrer una distancia en el menor tiempo posible.", "B": "estirar los músculos con amplitud.", "C": "vencer una carga máxima en un solo intento.", "D": "mantener un esfuerzo durante un tiempo prolongado."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "La flexibilidad es la capacidad de:", "opciones": {"A": "cargar un peso elevado.", "B": "correr muy rápido.", "C": "mantener el esfuerzo por mucho tiempo.", "D": "mover las articulaciones con gran amplitud."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «amplitud» significa:", "opciones": {"A": "rapidez de reacción.", "B": "fuerza máxima.", "C": "extensión o rango de un movimiento.", "D": "cansancio acumulado."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué las capacidades no se desarrollan igual en todas las personas?", "opciones": {"A": "Porque el calentamiento no existe.", "B": "Porque dependen de la edad, los hábitos y la práctica regular.", "C": "Porque solo los atletas las tienen.", "D": "Porque la flexibilidad no se puede entrenar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante quiere mejorar su resistencia. ¿Qué actividad es más adecuada?", "opciones": {"A": "Hacer un solo salto largo.", "B": "Trotar de forma continua a un ritmo cómodo.", "C": "Levantar el máximo peso una vez.", "D": "Quedarse quieto mucho tiempo."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Antes de trabajar la velocidad, lo correcto es:", "opciones": {"A": "correr a máxima velocidad sin calentar.", "B": "estirar de forma brusca.", "C": "hacer un calentamiento que prepare músculos y articulaciones.", "D": "beber mucha agua de golpe."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la vuelta a la calma?", "opciones": {"A": "Para ayudar al cuerpo a recuperarse después del esfuerzo.", "B": "Para aumentar la intensidad del ejercicio.", "C": "Para reemplazar el calentamiento.", "D": "Para medir el rendimiento."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la fuerza se evidencia al:", "opciones": {"A": "saltar, empujar o cargar un peso.", "B": "trotar quince minutos.", "C": "estirar los brazos.", "D": "cambiar de dirección."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "Solo la fuerza es importante.", "B": "Las capacidades físicas básicas son cuatro y se desarrollan con práctica regular y calentamiento.", "C": "Las capacidades físicas no se pueden mejorar.", "D": "El calentamiento es opcional."}}]}, {"id": "2027-g7-p2-quiz2", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Minivoleibol: reglamento básico (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Minivoleibol: reglamento básico", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El minivoleibol es una versión del voleibol adaptada a la clase: se juega en una cancha pequeña, con la red más baja y equipos de cuatro jugadores. Cada jugada se inicia con un saque desde detrás de la línea de fondo. Un equipo puede tocar el balón hasta tres veces antes de pasarlo al otro lado, y un mismo jugador no puede golpearlo dos veces seguidas. Los golpes básicos son el voleo (toque de dedos por encima de la frente), el antebrazo (para recibir) y el saque.<br><br>Cuando un equipo recupera el saque, sus jugadores rotan una posición en el sentido de las manecillas del reloj, de modo que todos pasan por todas las posiciones. En la clase, cada jugada gana un punto, y el set se juega a 15 puntos con diferencia de dos. Son faltas tocar la red, el doble toque, retener el balón y enviarlo fuera de la cancha. Un balón que cae sobre la línea es válido."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuántos jugadores tiene un equipo de minivoleibol?", "opciones": {"A": "Seis.", "B": "Dos.", "C": "Once.", "D": "Cuatro."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos toques puede dar un equipo antes de pasar el balón al otro lado?", "opciones": {"A": "Hasta tres.", "B": "Hasta dos.", "C": "Hasta cuatro.", "D": "Solo uno."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué sentido rotan los jugadores al recuperar el saque?", "opciones": {"A": "En sentido contrario a las manecillas.", "B": "En el sentido de las manecillas del reloj.", "C": "De un lado a otro de la red.", "D": "No rotan nunca."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, el «voleo» es:", "opciones": {"A": "el toque de dedos por encima de la frente.", "B": "el saque desde la línea de fondo.", "C": "el golpe de antebrazos.", "D": "el golpe con el pie."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué en la clase se baja la red y se reduce la cancha?", "opciones": {"A": "Para volver el juego imposible.", "B": "Porque la red pesa demasiado.", "C": "Para adaptar el juego y facilitar la participación de todos.", "D": "Para que haya menos jugadores."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador golpea el balón dos veces seguidas. ¿Qué se sanciona?", "opciones": {"A": "Doble toque.", "B": "Retención.", "C": "Toque de red.", "D": "Nada."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "El marcador está 14 a 14 en un set a 15 puntos. ¿Qué sucede?", "opciones": {"A": "El set termina empatado.", "B": "Gana el equipo que sacó último.", "C": "Se juega un solo punto más.", "D": "El set continúa hasta que un equipo tenga ventaja de dos puntos."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se considera un balón que cae sobre la línea?", "opciones": {"A": "Fuera.", "B": "Válido.", "C": "Nulo.", "D": "Se repite la jugada."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la rotación, según el texto?", "opciones": {"A": "Para cansar al equipo rival.", "B": "Para evitar el saque.", "C": "Para que todos los jugadores pasen por todas las posiciones.", "D": "Para eliminar jugadores."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un jugador no está de acuerdo con una falta que se le pitó. ¿Cuál es la actitud más adecuada?", "opciones": {"A": "Discutir hasta que cambie la decisión.", "B": "Aceptar la decisión y seguir jugando con respeto.", "C": "Abandonar el juego.", "D": "Culpar a un compañero."}}]}, {"id": "2027-g7-p2-taller", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Capacidades físicas: concepto y medición (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Fuerza y resistencia: dos caras del esfuerzo", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "La fuerza y la resistencia suelen confundirse, pero se entrenan de manera distinta. La fuerza se desarrolla con ejercicios en los que el cuerpo vence una carga: sentadillas, flexiones de brazos, saltos o ejercicios con el propio peso corporal. Se trabajan series cortas con pausas de descanso y buena técnica. La resistencia aeróbica, en cambio, se entrena con esfuerzos continuos y moderados, como trotar, caminar rápido o montar bicicleta, de modo que el corazón y los pulmones se adapten a trabajar durante más tiempo.<br><br>Una forma sencilla de controlar la intensidad es la prueba del habla: si se puede conversar mientras se trota, el ritmo es adecuado; si no se puede pronunciar una frase completa, la intensidad es demasiado alta. En los juegos deportivos, la resistencia ayuda a mantener el rendimiento hasta el final del partido y la fuerza permite saltar, empujar o disparar con potencia. Aumentar la carga poco a poco y descansar lo necesario evita lesiones y mejora los resultados."}, {"id": 2, "titulo": "Velocidad y flexibilidad", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "La velocidad no es solo correr rápido: también incluye reaccionar a tiempo ante una señal, como el silbato del árbitro, y cambiar de dirección con agilidad. Se entrena con carreras cortas de máximo esfuerzo y descansos largos, para que el cuerpo recupere energía y cada repetición sea realmente rápida.<br><br>La flexibilidad, por su parte, se trabaja estirando los músculos de forma suave, sin rebotes, manteniendo cada posición entre diez y treinta segundos. Antes de la actividad se recomiendan movimientos dinámicos, como círculos de brazos o balanceos de piernas, que preparan las articulaciones; los estiramientos prolongados se dejan para el final, cuando los músculos están calientes. Una buena flexibilidad permite moverse con mayor amplitud, mejora la postura y reduce el riesgo de lesiones. Sin embargo, forzar un estiramiento hasta sentir dolor no mejora la flexibilidad y puede causar daño."}, {"id": 3, "titulo": "La batería de test físicos", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Para conocer cómo están sus capacidades físicas, los estudiantes realizan una batería de test, es decir, un conjunto de pruebas aplicadas en una misma jornada. En esta clase se usan cuatro: el salto largo sin impulso mide la fuerza de las piernas; las abdominales en un minuto miden la resistencia muscular del abdomen; el sit and reach, o flexión de tronco sentado, mide la flexibilidad de la espalda baja y de la parte trasera de las piernas; y la carrera de 30 metros mide la velocidad.<br><br>Primero se hace un calentamiento general y se explica cada prueba con una demostración. Después se rota por estaciones y un compañero anota los resultados en la ficha. Medir las capacidades permite conocer el punto de partida y comprobar, con una segunda medición llamada retest, si el trabajo realizado dio resultado. Una prueba no mide a la persona, sino el estado de una capacidad en un momento determinado."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿con qué se desarrolla la fuerza?", "opciones": {"A": "Con esfuerzos continuos y suaves.", "B": "Con estiramientos prolongados.", "C": "Con ejercicios en los que el cuerpo vence una carga.", "D": "Únicamente con partidos."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué ejemplos de resistencia aeróbica menciona el texto?", "opciones": {"A": "Sentadillas y flexiones de brazos.", "B": "Trotar, caminar rápido o montar bicicleta.", "C": "Saltos con carga máxima.", "D": "Estiramientos de pie."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «intensidad» se refiere a:", "opciones": {"A": "cuánto dura la clase.", "B": "el tamaño de la cancha.", "C": "el número de jugadores.", "D": "qué tan fuerte o exigente es el esfuerzo."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto afirma que fuerza y resistencia «se entrenan de manera distinta»?", "opciones": {"A": "Porque son la misma capacidad.", "B": "Porque solo una se usa en el deporte.", "C": "Porque cada una exige un tipo de esfuerzo diferente: cargas cortas frente a esfuerzo continuo.", "D": "Porque la resistencia no necesita descanso."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Durante un trote, un estudiante no puede decir una frase completa sin jadear. ¿Qué debe hacer?", "opciones": {"A": "Bajar el ritmo para reducir la intensidad.", "B": "Subir el ritmo.", "C": "Dejar de respirar profundo.", "D": "Mantener la intensidad sin cambios."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para empezar a trabajar la fuerza con seguridad, conviene:", "opciones": {"A": "cargar el máximo peso desde el inicio.", "B": "omitir los descansos.", "C": "usar el propio peso corporal y cuidar la técnica.", "D": "entrenar sin calentar."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero dice que «entre más pesado, mejor» para ganar fuerza. Según el texto, su idea:", "opciones": {"A": "es correcta, porque el peso máximo es lo único que importa.", "B": "no es correcta, porque la carga se aumenta poco a poco con buena técnica y descanso.", "C": "es correcta, porque la técnica no influye.", "D": "no es correcta, porque la fuerza no se entrena."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "Además de correr rápido, ¿qué incluye la velocidad?", "opciones": {"A": "Solo mantener el esfuerzo por mucho tiempo.", "B": "Estirar los músculos.", "C": "Cargar peso.", "D": "Reaccionar a tiempo ante una señal y cambiar de dirección."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuánto tiempo debe mantenerse cada posición de estiramiento?", "opciones": {"A": "Un segundo, con rebotes.", "B": "Cinco minutos.", "C": "Hasta sentir dolor.", "D": "Entre diez y treinta segundos."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, la palabra «agilidad» significa:", "opciones": {"A": "fuerza máxima.", "B": "facilidad y rapidez para moverse y cambiar de posición.", "C": "cansancio acumulado.", "D": "calentamiento previo."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué se dejan descansos largos entre las carreras de velocidad?", "opciones": {"A": "Para que el cuerpo se enfríe por completo.", "B": "Para evitar correr.", "C": "Para recuperar energía y que cada repetición sea realmente rápida.", "D": "Para que el entrenamiento dure más."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Antes de un partido, la mejor preparación de la flexibilidad es:", "opciones": {"A": "hacer movimientos dinámicos, como círculos de brazos y balanceos de piernas.", "B": "hacer estiramientos prolongados con rebotes.", "C": "no mover las articulaciones.", "D": "estirar hasta sentir dolor."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "Una estudiante siente dolor al estirar. ¿Qué debe hacer?", "opciones": {"A": "Forzar más hasta que ceda.", "B": "Reducir el estiramiento hasta un punto cómodo, sin dolor.", "C": "Rebotar para ganar amplitud.", "D": "Ignorar la señal del cuerpo."}}, {"n": 14, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué los estiramientos prolongados se dejan para el final?", "opciones": {"A": "Porque los músculos están calientes y se estiran mejor.", "B": "Porque antes de la actividad no hay tiempo.", "C": "Porque reemplazan la vuelta a la calma.", "D": "Porque el calentamiento los prohíbe."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué mide el sit and reach (flexión de tronco sentado)?", "opciones": {"A": "La fuerza de los brazos.", "B": "La velocidad de reacción.", "C": "La resistencia aeróbica.", "D": "La flexibilidad de la espalda baja y de la parte trasera de las piernas."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, una «batería de test» es:", "opciones": {"A": "un aparato eléctrico para medir.", "B": "un descanso entre ejercicios.", "C": "un partido por equipos.", "D": "un conjunto de pruebas aplicadas en una misma jornada."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Para qué sirve el retest?", "opciones": {"A": "Para castigar los malos resultados.", "B": "Para comprobar si el trabajo realizado produjo mejoras.", "C": "Para borrar la primera ficha.", "D": "Para cambiar el reglamento."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Para medir la resistencia muscular del abdomen se usa:", "opciones": {"A": "el salto largo sin impulso.", "B": "la carrera de 30 metros.", "C": "las abdominales en un minuto.", "D": "el sit and reach."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "La frase «una prueba no mide a la persona, sino el estado de una capacidad» significa que:", "opciones": {"A": "un mal resultado hoy no define a la persona y puede mejorar con la práctica.", "B": "quien salta menos no sirve para el deporte.", "C": "solo importa el mejor resultado del curso.", "D": "las pruebas no sirven para nada."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "A partir de las tres lecturas, ¿cómo se relacionan el entrenamiento y los test físicos?", "opciones": {"A": "Los test muestran el estado de cada capacidad, y un entrenamiento adecuado permite mejorarla y comprobarlo con un retest.", "B": "Los test reemplazan al entrenamiento.", "C": "El entrenamiento solo sirve si se evita medir.", "D": "Los test se hacen para dejar fuera a quienes tienen menos fuerza."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g8-p2-quiz1", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Capacidades físicas y pruebas que las miden (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Capacidades físicas y pruebas que las miden", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las capacidades físicas básicas son la resistencia, la fuerza, la velocidad y la flexibilidad. Para saber cómo está cada una se usan pruebas físicas, que son ejercicios estandarizados: se hacen siempre con el mismo procedimiento. La resistencia aeróbica se mide con el Course Navette o test de ida y vuelta de 20 metros, en el que se corre entre dos líneas al ritmo de una señal sonora que se acelera. La resistencia muscular del abdomen se mide con las abdominales en un minuto. La fuerza explosiva de las piernas se mide con el salto largo sin impulso, y la velocidad, con una carrera de 50 metros cronometrada.<br><br>Las pruebas no sirven para comparar a unos estudiantes con otros, sino para conocer el punto de partida de cada uno y comprobar su progreso. Para que los resultados sean confiables, se hacen después de un calentamiento, con la técnica correcta y en condiciones similares cada vez."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué prueba mide la resistencia aeróbica?", "opciones": {"A": "El salto largo sin impulso.", "B": "El Course Navette.", "C": "La carrera de 50 metros.", "D": "Las abdominales en un minuto."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué capacidad mide la carrera de 50 metros cronometrada?", "opciones": {"A": "La resistencia aeróbica.", "B": "La flexibilidad.", "C": "La velocidad.", "D": "La fuerza abdominal."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿para qué sirven las pruebas físicas?", "opciones": {"A": "Para conocer el punto de partida y comprobar el progreso de cada estudiante.", "B": "Para clasificar quién es el mejor del curso.", "C": "Para reemplazar la clase.", "D": "Para evitar el calentamiento."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «estandarizadas» significa que las pruebas:", "opciones": {"A": "se hacen sin ninguna regla.", "B": "se realizan siempre con el mismo procedimiento.", "C": "solo las conoce el docente.", "D": "cambian cada día."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la señal sonora del Course Navette se va acelerando?", "opciones": {"A": "Para distraer a los corredores.", "B": "Para que la prueba sea más corta.", "C": "Para evitar que lleguen a la línea.", "D": "Para aumentar la exigencia poco a poco hasta el límite de cada estudiante."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Tras tres meses, un estudiante completa más tramos en el Course Navette. ¿Qué indica esto?", "opciones": {"A": "Que su flexibilidad empeoró.", "B": "Que su velocidad bajó.", "C": "Que su resistencia aeróbica mejoró.", "D": "Que no calentó."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para medir la fuerza explosiva de las piernas se utiliza:", "opciones": {"A": "el salto largo sin impulso.", "B": "el Course Navette.", "C": "la carrera de 50 metros.", "D": "las abdominales en un minuto."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se hace calentamiento antes de las pruebas?", "opciones": {"A": "Para que la prueba dure menos.", "B": "Para que los resultados sean confiables y se evite lesionarse.", "C": "Porque lo exige el reglamento de cada deporte.", "D": "Para recuperarse después."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, las abdominales en un minuto miden:", "opciones": {"A": "la velocidad de reacción.", "B": "la flexibilidad.", "C": "la fuerza de los brazos.", "D": "la resistencia muscular del abdomen."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué idea resume mejor el texto?", "opciones": {"A": "Las pruebas físicas permiten medir cada capacidad y seguir el progreso personal, si se aplican correctamente.", "B": "Las pruebas sirven para comparar a los estudiantes y dejar fuera a los más lentos.", "C": "Las pruebas físicas no necesitan técnica.", "D": "Solo la resistencia se puede medir."}}]}, {"id": "2027-g8-p2-quiz2", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Reglamento de balonmano y microfútbol (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Reglamento de balonmano y microfútbol", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El balonmano se juega con las manos entre dos equipos; en la versión escolar, cada equipo tiene un portero y cinco o seis jugadores de campo. El objetivo es lanzar el balón a la portería contraria. Un jugador puede dar como máximo tres pasos con el balón en las manos y no puede retenerlo más de tres segundos sin moverse. Si bota el balón y lo toma con las dos manos, no puede volver a botarlo: eso se llama doble regate. Solo el portero puede entrar al área de portería. Las faltas graves, como golpear o empujar con violencia, pueden sancionarse con una suspensión de dos minutos fuera del juego. Cuando una falta impide una clara opción de gol, se cobra un lanzamiento de siete metros.<br><br>El microfútbol se juega con los pies en una cancha pequeña, entre equipos de cinco jugadores. Las faltas se sancionan con tiro libre, y la tarjeta amarilla advierte, mientras que la roja expulsa al jugador. En ambos deportes los equipos deben cooperar: pasar, ocupar espacios y comunicarse."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "En balonmano, ¿cuántos pasos como máximo se pueden dar con el balón en las manos?", "opciones": {"A": "Uno.", "B": "Tres.", "C": "Cinco.", "D": "Diez."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Quién puede entrar al área de portería en balonmano?", "opciones": {"A": "Todos los jugadores.", "B": "Solo el portero.", "C": "Solo los defensas.", "D": "El árbitro y los delanteros."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el doble regate consiste en:", "opciones": {"A": "botar el balón, tomarlo con las dos manos y volver a botarlo.", "B": "lanzar dos veces seguidas a la portería.", "C": "pasar el balón a dos compañeros.", "D": "hacer dos saques seguidos."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, una «suspensión» de dos minutos es:", "opciones": {"A": "un premio por buen juego.", "B": "un descanso entre tiempos.", "C": "una salida temporal del juego como sanción.", "D": "un cambio de portero."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué solo el portero puede entrar al área de portería?", "opciones": {"A": "Para que los demás jugadores descansen.", "B": "Para proteger la portería de ataques demasiado cercanos.", "C": "Para hacer el juego más lento.", "D": "Porque los demás no saben jugar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador de balonmano se queda cinco segundos sin moverse con el balón en las manos. ¿Qué falta comete?", "opciones": {"A": "Retener el balón más de tres segundos.", "B": "Doble regate.", "C": "Pasos.", "D": "Ninguna falta."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un partido de microfútbol, un jugador recibe tarjeta roja. ¿Qué significa?", "opciones": {"A": "Que recibe una advertencia.", "B": "Que debe descansar un minuto.", "C": "Que se cobra tiro libre a su favor.", "D": "Que es expulsado del partido."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Con qué parte del cuerpo se juega el microfútbol?", "opciones": {"A": "Con las manos.", "B": "Con raquetas.", "C": "Con palos.", "D": "Con los pies."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se cobra un lanzamiento de siete metros cuando una falta impide una clara opción de gol?", "opciones": {"A": "Porque compensa la oportunidad de gol que perdió el equipo atacante.", "B": "Porque premia la falta.", "C": "Porque termina el partido.", "D": "Porque cambia al portero."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué tienen en común el balonmano y el microfútbol según el texto?", "opciones": {"A": "Se juegan sin árbitro.", "B": "Se juegan solo con las manos.", "C": "Exigen cooperación entre los jugadores y respeto por las reglas.", "D": "No tienen sanciones."}}]}, {"id": "2027-g8-p2-taller", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Resultados de las pruebas físicas (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Course Navette y velocidad de 50 metros", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El Course Navette, también llamado test de Léger, mide la resistencia aeróbica. El estudiante corre de ida y vuelta entre dos líneas separadas 20 metros, al ritmo de una señal sonora que se acelera cada cierto tiempo. En cada cruce debe pisar o sobrepasar la línea antes de la señal siguiente. La prueba termina cuando no logra llegar a la línea a tiempo dos veces seguidas, y se registra el último nivel o tramo alcanzado.<br><br>Para medir la velocidad se usa la carrera de 50 metros con salida de pie, cronometrada por un compañero. Aquí el esfuerzo es máximo, pero muy corto. En la primera prueba, administrar bien el esfuerzo es clave; en la segunda, lo importante es la reacción al salir y mantener la técnica de carrera hasta la meta. Los dos resultados se anotan en una ficha para poder compararlos con la medición final."}, {"id": 2, "titulo": "Fuerza y flexibilidad: la importancia de la técnica", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Las pruebas de fuerza dependen mucho de la técnica. En el salto largo sin impulso, el estudiante se coloca detrás de una línea con los pies separados al ancho de los hombros, flexiona las rodillas, balancea los brazos hacia atrás y salta hacia adelante con ambos pies; se mide desde la línea hasta el talón más cercano. En las abdominales en un minuto, las rodillas van flexionadas, los pies apoyados y las manos cruzadas sobre el pecho; la repetición solo cuenta si el tronco sube hasta tocar los muslos y vuelve a apoyarse en el suelo.<br><br>Si la técnica no es correcta, el resultado no refleja la capacidad real y puede incluso causar molestias. Por eso conviene explicar y demostrar cada prueba antes de aplicarla, y calentar los músculos que se van a usar."}, {"id": 3, "titulo": "De la tabla a la conclusión: analizar mis resultados", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Los datos de las pruebas solo son útiles si se analizan. El primer paso es organizarlos en una tabla: una columna para cada prueba y una fila para la medición inicial y otra para el retest. El segundo paso es graficarlos; un gráfico de barras permite ver de un vistazo en qué prueba hubo más cambio. El tercer paso es interpretar: si el número de tramos del Course Navette aumentó, la resistencia mejoró; si el tiempo de los 50 metros disminuyó, la velocidad mejoró; si la distancia del salto aumentó, la potencia de las piernas mejoró.<br><br>Cuando un resultado no cambia o empeora, se busca la causa: poca práctica, falta de descanso o técnica incorrecta. Finalmente se redactan las conclusiones y se plantea qué se hará distinto en el siguiente periodo. El análisis no busca encontrar culpables, sino tomar decisiones para entrenar mejor."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué capacidad mide el Course Navette?", "opciones": {"A": "La resistencia aeróbica.", "B": "La velocidad.", "C": "La fuerza.", "D": "La flexibilidad."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿A qué distancia están las dos líneas del Course Navette?", "opciones": {"A": "10 metros.", "B": "50 metros.", "C": "20 metros.", "D": "100 metros."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuándo termina la prueba del Course Navette?", "opciones": {"A": "Cuando pasan 12 minutos.", "B": "Cuando el estudiante lo decide.", "C": "Cuando suena la primera señal.", "D": "Cuando no logra llegar a la línea a tiempo dos veces seguidas."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «administrar el esfuerzo» significa:", "opciones": {"A": "gastar toda la energía al inicio.", "B": "evitar hacer ejercicio.", "C": "distribuir la energía de forma adecuada durante la prueba.", "D": "contar los metros recorridos."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la señal del Course Navette se acelera cada cierto tiempo?", "opciones": {"A": "Para que la prueba sea más corta.", "B": "Para aumentar la exigencia hasta el límite de cada estudiante.", "C": "Para confundir a los corredores.", "D": "Para que nadie llegue a la línea."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "En los 50 metros, un estudiante pierde velocidad al final porque cruza los brazos. ¿Qué debe corregir?", "opciones": {"A": "Detenerse antes de la meta.", "B": "Mantener la técnica de carrera hasta la meta.", "C": "Correr más lento todo el recorrido.", "D": "Mirar al piso."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué conviene anotar los resultados en una ficha?", "opciones": {"A": "Porque reemplaza la prueba.", "B": "Porque así se evita repetir la prueba.", "C": "Porque sirve para clasificar a los estudiantes.", "D": "Porque permite compararlos con la medición final y ver el progreso."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Desde dónde se mide el salto largo sin impulso?", "opciones": {"A": "Desde la punta del pie hasta la meta.", "B": "Desde la línea hasta la mano.", "C": "Desde el centro de la cancha.", "D": "Desde la línea hasta el talón más cercano."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "Una repetición de abdominales solo cuenta si:", "opciones": {"A": "se hace lo más rápido posible.", "B": "se levantan los pies del suelo.", "C": "el tronco sube hasta tocar los muslos y vuelve a apoyarse en el suelo.", "D": "se usan las manos para impulsarse."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, la palabra «reflejar» significa:", "opciones": {"A": "mostrar o representar fielmente.", "B": "ocultar.", "C": "repetir.", "D": "corregir."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué conviene demostrar cada prueba antes de aplicarla?", "opciones": {"A": "Para que los estudiantes se cansen menos.", "B": "Para que todos la hagan con la técnica correcta y el resultado sea válido.", "C": "Para que el docente no tenga que corregir.", "D": "Para que la prueba sea más rápida."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante hace abdominales impulsándose con las manos. ¿Qué debe corregir?", "opciones": {"A": "Apoyar las manos detrás de la cabeza y tirar.", "B": "Estirar las rodillas.", "C": "Hacerlas con los pies en el aire.", "D": "Mantener las manos cruzadas sobre el pecho."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "En el salto largo sin impulso, ¿qué movimiento ayuda a impulsarse?", "opciones": {"A": "Mantener las piernas rígidas.", "B": "Saltar con un solo pie.", "C": "Flexionar las rodillas y balancear los brazos hacia atrás antes del salto.", "D": "Dejar los brazos pegados al cuerpo."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Dos estudiantes tienen la misma fuerza, pero uno hace mal la técnica. Según el texto, ¿qué pasará con sus resultados?", "opciones": {"A": "Los resultados serán iguales.", "B": "El de mala técnica saltará más lejos.", "C": "El de mala técnica obtendrá un resultado que no refleja su capacidad real.", "D": "La técnica no cambia nada."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué tipo de gráfico se recomienda para comparar las pruebas?", "opciones": {"A": "Un gráfico de barras.", "B": "Un mapa.", "C": "Un dibujo libre.", "D": "Un calendario."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, «interpretar» los datos significa:", "opciones": {"A": "borrarlos.", "B": "explicar qué significan.", "C": "repetirlos.", "D": "copiarlos."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "Si el tiempo de los 50 metros disminuyó, ¿por qué se dice que la velocidad mejoró?", "opciones": {"A": "Porque corrió menos metros.", "B": "Porque recorrió la misma distancia en menos tiempo.", "C": "Porque descansó más.", "D": "Porque cambió de pista."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un estudiante mantuvo el mismo resultado en las abdominales. ¿Qué debe hacer?", "opciones": {"A": "Buscar posibles causas, como poca práctica o técnica incorrecta, y ajustar su trabajo.", "B": "Abandonar la prueba.", "C": "Borrar el resultado.", "D": "Culpar al compañero que anotó."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿para qué se analizan los resultados?", "opciones": {"A": "Para señalar a quien rinde menos.", "B": "Para evitar el retest.", "C": "Para clasificar a los estudiantes.", "D": "Para tomar decisiones y entrenar mejor, no para buscar culpables."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Después de leer las tres lecturas, ¿cuál es el mejor camino para evaluar la condición física?", "opciones": {"A": "Medir con la técnica correcta, organizar los datos en tabla y gráfica, interpretarlos y decidir cómo mejorar.", "B": "Medir una sola vez y compararse con el mejor del curso.", "C": "Anotar solo los mejores resultados.", "D": "Evitar el retest para no desanimarse."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g9-p2-quiz1", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Condición física y frecuencia cardiaca (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Condición física y frecuencia cardiaca", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "La condición física es el estado general del cuerpo para realizar esfuerzos y recuperarse bien. Tiene cuatro componentes que se trabajan en la clase: la resistencia, la fuerza funcional (la que se usa en movimientos de la vida diaria y del deporte, como empujar, saltar o levantarse), la velocidad y la flexibilidad.<br><br>Una forma de controlar el esfuerzo es la frecuencia cardiaca, es decir, los latidos del corazón por minuto. Se mide en reposo y durante el ejercicio, tomando el pulso en el cuello o en la muñeca durante 15 segundos y multiplicando por cuatro. La frecuencia cardiaca máxima se estima restando la edad a 220. A partir de ese valor se establecen zonas: entre el 50 % y el 60 % el esfuerzo es muy suave; entre el 60 % y el 70 %, suave, y mejora la resistencia de base; entre el 70 % y el 80 %, moderado; y por encima del 80 %, intenso, y solo se mantiene poco tiempo. Trabajar en la zona adecuada permite mejorar sin exagerar."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuáles son los cuatro componentes de la condición física?", "opciones": {"A": "Resistencia, fuerza funcional, velocidad y flexibilidad.", "B": "Peso, talla, edad y sexo.", "C": "Solo fuerza y velocidad.", "D": "Equilibrio, ritmo, lateralidad y postura."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se estima la frecuencia cardiaca máxima?", "opciones": {"A": "Sumando la edad a 220.", "B": "Multiplicando la edad por 10.", "C": "Dividiendo 220 entre la edad.", "D": "Restando la edad a 220."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Si se toma el pulso durante 15 segundos, ¿por cuánto se multiplica para obtener los latidos por minuto?", "opciones": {"A": "Por dos.", "B": "Por cuatro.", "C": "Por diez.", "D": "Por seis."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «fuerza funcional» es la que:", "opciones": {"A": "se usa en movimientos de la vida diaria y del deporte.", "B": "solo se usa en el gimnasio.", "C": "se mide con el pulso.", "D": "depende de la edad."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué conviene trabajar en la zona de frecuencia cardiaca adecuada?", "opciones": {"A": "Para evitar medir el pulso.", "B": "Para mejorar sin exagerar el esfuerzo.", "C": "Para correr más rápido siempre.", "D": "Para no calentar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una estudiante de 16 años quiere estimar su frecuencia cardiaca máxima. ¿Cuál es el valor aproximado?", "opciones": {"A": "236 latidos por minuto.", "B": "220 latidos por minuto.", "C": "204 latidos por minuto.", "D": "16 latidos por minuto."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante cuenta 20 latidos en 15 segundos. ¿Cuántos latidos por minuto tiene?", "opciones": {"A": "60.", "B": "35.", "C": "100.", "D": "80."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿a qué tipo de esfuerzo corresponde la zona entre el 70 % y el 80 %?", "opciones": {"A": "Moderado.", "B": "Muy suave.", "C": "Intenso.", "D": "Máximo."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el esfuerzo por encima del 80 % solo se mantiene poco tiempo?", "opciones": {"A": "Porque el reglamento lo prohíbe.", "B": "Porque el pulso se detiene.", "C": "Porque el cuerpo no puede sostener un esfuerzo tan intenso sin fatigarse.", "D": "Porque no hace falta."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "Solo importa la fuerza.", "B": "Controlar la frecuencia cardiaca ayuda a trabajar la condición física con seguridad.", "C": "El pulso no sirve para entrenar.", "D": "Todos deben trabajar al máximo."}}]}, {"id": "2027-g9-p2-quiz2", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Principios del entrenamiento y autocontrol corporal (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Principios del entrenamiento y autocontrol corporal", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Para mejorar la condición física no basta con hacer ejercicio de vez en cuando: el entrenamiento sigue principios. El principio de sobrecarga indica que el cuerpo mejora cuando recibe un esfuerzo algo mayor al habitual; el de progresión, que esa carga debe aumentar de manera gradual; el de continuidad, que se debe entrenar con regularidad, porque si se abandona la práctica los beneficios se pierden; y el de individualidad, que cada persona tiene un punto de partida y una respuesta distinta. También son indispensables el descanso y la recuperación, porque es en ese tiempo cuando el cuerpo se adapta y se fortalece.<br><br>El autocontrol corporal completa el entrenamiento: consiste en respirar de forma rítmica durante el esfuerzo, relajar los músculos al terminar con respiraciones lentas y hacer estiramientos suaves, sin rebotes, para volver a la calma."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Inferencial", "enunciado": "Si un estudiante siempre hace exactamente el mismo esfuerzo, ¿qué es lo más probable?", "opciones": {"A": "Que mejore cada vez más rápido.", "B": "Que su cuerpo deje de mejorar, porque no recibe un estímulo mayor.", "C": "Que no necesite descansar.", "D": "Que gane flexibilidad sin trabajarla."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el principio de progresión indica que la carga debe:", "opciones": {"A": "mantenerse siempre igual.", "B": "subir de golpe.", "C": "aumentar de manera gradual.", "D": "eliminarse."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué sucede si se abandona la práctica?", "opciones": {"A": "Los beneficios aumentan.", "B": "Los beneficios se mantienen para siempre.", "C": "Los beneficios se triplican.", "D": "Los beneficios se pierden."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, el principio de «individualidad» significa que:", "opciones": {"A": "todos deben entrenar exactamente igual.", "B": "solo se entrena en equipo.", "C": "se entrena sin descanso.", "D": "cada persona tiene su propio punto de partida y respuesta."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el descanso es indispensable?", "opciones": {"A": "Porque en ese tiempo el cuerpo se adapta y se fortalece.", "B": "Porque reemplaza al ejercicio.", "C": "Porque impide la progresión.", "D": "Porque evita la sobrecarga."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante entrena dos veces al mes y no ve mejoras. ¿Qué principio no está cumpliendo?", "opciones": {"A": "El descanso.", "B": "La continuidad.", "C": "La individualidad.", "D": "La sobrecarga."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una persona trota siempre 10 minutos al mismo ritmo y quiere seguir mejorando. Debe:", "opciones": {"A": "trotar menos cada semana.", "B": "aumentar poco a poco la duración o la intensidad.", "C": "cambiar de deporte cada día.", "D": "suprimir el descanso."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el autocontrol corporal incluye:", "opciones": {"A": "respirar de forma rítmica, relajar los músculos y estirar suavemente.", "B": "entrenar sin descanso.", "C": "evitar la respiración.", "D": "hacer estiramientos con rebotes."}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Después de una sesión intensa, un estudiante se siente agitado. ¿Qué es lo más adecuado?", "opciones": {"A": "Hacer respiraciones lentas y estiramientos suaves para volver a la calma.", "B": "Seguir corriendo a máxima velocidad.", "C": "Dejar de respirar profundo.", "D": "Sentarse sin moverse ni respirar."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "Basta con entrenar al azar.", "B": "El descanso no importa.", "C": "Un entrenamiento eficaz combina principios, descanso y autocontrol corporal.", "D": "Solo importa la intensidad."}}]}, {"id": "2027-g9-p2-taller", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Plan personal de trabajo físico (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Del diagnóstico al objetivo", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El plan personal de trabajo físico dura cuatro semanas y comienza con un diagnóstico: los resultados del test inicial, como el Course Navette, el salto largo, las abdominales en un minuto y la flexibilidad, más una reflexión sobre los hábitos de sueño, alimentación e hidratación. Con esa información, el estudiante elige una capacidad prioritaria y formula un objetivo que sea específico, medible y alcanzable en cuatro semanas, por ejemplo: «aumentar cinco abdominales en un minuto».<br><br>Un objetivo como «ponerme en forma» es demasiado vago, porque no permite saber si se cumplió. También debe ser realista: mejorar poco a poco es más seguro y motivante que proponerse cambios enormes. Finalmente se define cómo se comprobará el avance: con el mismo test al final del plan."}, {"id": 2, "titulo": "Estructura de la semana y de la sesión", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Con el objetivo definido se organiza la semana. Un plan para estudiantes de bachillerato suele incluir tres o cuatro sesiones semanales, alternando días de trabajo con días de descanso para que el cuerpo se recupere. Cada sesión tiene tres partes: el calentamiento, de unos diez minutos, con movilidad articular y ejercicios suaves; la parte principal, donde se trabaja la capacidad elegida con circuitos, carrera continua o intervalos; y la vuelta a la calma, con respiración lenta y estiramientos.<br><br>La carga se aumenta gradualmente: por ejemplo, la semana uno puede tener menos repeticiones o menos minutos que la semana cuatro. Los principios de continuidad y progresión se cumplen cuando se respeta el calendario y se sube la carga poco a poco. Si un día hay dolor, mareo o cansancio extremo, la sesión se suspende o se reduce."}, {"id": 3, "titulo": "Autocontrol, registro y sustentación", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Durante las cuatro semanas, cada sesión se anota en una bitácora: la fecha, el ejercicio, la duración, la frecuencia cardiaca o la percepción del esfuerzo, y cómo se sintió la persona. La bitácora permite ver si se cumple el calendario y detectar señales de alerta. El autocontrol corporal también incluye técnicas de relajación, como la respiración lenta —inhalar por la nariz, sostener un momento y soltar el aire por la boca— y estiramientos suaves al terminar.<br><br>Al final del plan se repite el test inicial, el retest, y se compara con el diagnóstico. En la sustentación, el estudiante presenta su objetivo, muestra sus datos y explica si logró la meta, qué factores ayudaron o dificultaron el proceso y qué haría distinto. Una buena sustentación se apoya en datos, no solo en opiniones."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto dura el plan personal de trabajo físico?", "opciones": {"A": "Cuatro semanas.", "B": "Dos semanas.", "C": "Un año.", "D": "Un día."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿con qué comienza el plan?", "opciones": {"A": "Con una competencia.", "B": "Con un diagnóstico basado en el test inicial y los hábitos.", "C": "Con el retest.", "D": "Con la sustentación."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, un objetivo «específico» es el que:", "opciones": {"A": "es muy general.", "B": "no se puede medir.", "C": "cambia cada día.", "D": "está bien definido y no deja dudas."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué «ponerme en forma» no es un buen objetivo?", "opciones": {"A": "Porque es demasiado fácil.", "B": "Porque es vago y no permite saber si se cumplió.", "C": "Porque está prohibido.", "D": "Porque requiere un gimnasio."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cuál de estos es un objetivo bien formulado?", "opciones": {"A": "Ser el mejor del colegio algún día.", "B": "Hacer ejercicio cuando haya ganas.", "C": "Aumentar cinco abdominales en un minuto en cuatro semanas.", "D": "Ponerme en forma pronto."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cómo puede comprobar el estudiante si logró su objetivo?", "opciones": {"A": "Preguntando a un amigo.", "B": "Repitiendo el mismo test al final del plan.", "C": "Esperando a sentirse mejor.", "D": "No es necesario comprobarlo."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿por qué es mejor mejorar poco a poco?", "opciones": {"A": "Porque se avanza menos y no se necesita descanso.", "B": "Porque es más seguro y motivante.", "C": "Porque evita registrar datos.", "D": "Porque así no hay objetivos."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuántas sesiones semanales suele incluir el plan?", "opciones": {"A": "Tres o cuatro.", "B": "Una.", "C": "Siete.", "D": "Diez."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuáles son las tres partes de cada sesión?", "opciones": {"A": "Saque, remate y bloqueo.", "B": "Diagnóstico, objetivo y sustentación.", "C": "Test, retest y bitácora.", "D": "Calentamiento, parte principal y vuelta a la calma."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, aumentar la carga «gradualmente» significa:", "opciones": {"A": "de un solo golpe.", "B": "solo al final.", "C": "poco a poco.", "D": "nunca."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué la semana uno puede tener menos carga que la semana cuatro?", "opciones": {"A": "Porque la semana uno no se entrena.", "B": "Porque la carga debe aumentar de forma progresiva.", "C": "Porque se pierde la condición.", "D": "Porque la semana cuatro es de descanso total."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante siente mareo en medio de la sesión. ¿Qué debe hacer?", "opciones": {"A": "Suspender o reducir la sesión.", "B": "Seguir con más intensidad.", "C": "Ignorar la señal.", "D": "Terminar corriendo."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "En la semana uno un estudiante trota 10 minutos. ¿Qué es coherente para la semana cuatro?", "opciones": {"A": "60 minutos de golpe.", "B": "Los mismos 10 minutos sin cambio.", "C": "No trotar.", "D": "Unos 16 minutos, subiendo poco a poco."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero dice que un plan sin días de descanso mejora más rápido. Según el texto:", "opciones": {"A": "no es correcto, porque el descanso permite que el cuerpo se recupere y es parte del plan.", "B": "es correcto, porque el descanso estorba.", "C": "es correcto si se entrena el doble.", "D": "no es correcto, porque los planes no tienen estructura."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué se anota en la bitácora de cada sesión?", "opciones": {"A": "Solo la nota final.", "B": "Únicamente el nombre del docente.", "C": "El resultado de los demás compañeros.", "D": "La fecha, el ejercicio, la duración, el esfuerzo y cómo se sintió la persona."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, la «sustentación» es:", "opciones": {"A": "un descanso al final del plan.", "B": "una prueba de velocidad.", "C": "la presentación y explicación del plan con datos y argumentos.", "D": "un registro de convivencia."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué se repite el test inicial al final del plan?", "opciones": {"A": "Para comparar con el diagnóstico y saber si hubo mejora.", "B": "Para castigar los resultados bajos.", "C": "Para cambiar el objetivo.", "D": "Para eliminar la bitácora."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Una estudiante no logró su meta. ¿Qué debe hacer en la sustentación?", "opciones": {"A": "Ocultar los resultados.", "B": "Culpar al docente.", "C": "Explicar con datos qué factores influyeron y qué haría distinto.", "D": "No presentarse."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué una buena sustentación debe apoyarse en datos?", "opciones": {"A": "Porque los datos son decorativos.", "B": "Porque así se evita explicar.", "C": "Porque las opiniones están prohibidas.", "D": "Porque permite evaluar el progreso con evidencia y no solo con opiniones."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Considerando las tres lecturas, un plan personal de trabajo físico bien hecho:", "opciones": {"A": "se improvisa cada día según el ánimo.", "B": "evita el retest para no comparar.", "C": "parte de un diagnóstico, organiza la carga con descansos, se registra y se evalúa al final con datos.", "D": "prescinde de la relajación y del descanso."}, "textoIds": [1, 2, 3]}]}];
